const setLocalStorageSafely = (key: string, value: string) => {
  try {
    window.localStorage.setItem(key, value);
    return true;
  } catch (error) {
    const reason = error instanceof Error ? `${error.name}: ${error.message}` : String(error);
    console.warn(`[local-storage] No se pudo guardar ${key}. La aplicacion seguira funcionando.`, reason);
    return false;
  }
};

const setJsonLocalStorageSafely = (key: string, value: unknown) => {
  try {
    return setLocalStorageSafely(key, JSON.stringify(value));
  } catch (error) {
    const reason = error instanceof Error ? `${error.name}: ${error.message}` : String(error);
    console.warn(`[local-storage] No se pudo serializar ${key}. La aplicacion seguira funcionando.`, reason);
    return false;
  }
};

const compactAttachmentsForLocalBackup = (value: string) => {
  try {
    const attachments = JSON.parse(value);
    if (!Array.isArray(attachments)) return value;
    return JSON.stringify(
      attachments.map((attachment) => {
        if (!attachment || typeof attachment !== "object") return attachment;
        const metadata = { ...(attachment as Record<string, unknown>) };
        delete metadata.dataUrl;
        return metadata;
      }),
    );
  } catch {
    return value.length <= 64_000 ? value : "";
  }
};

// Supabase es la fuente principal. El respaldo del navegador conserva los
// registros, pero excluye medios pesados y URLs temporales que pueden superar
// rapidamente la cuota de localStorage y derribar la interfaz.
const compressImageBase64 = (file: File, maxWidth = 360, quality = 0.8): Promise<string> =>
  new Promise((resolve) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new window.Image();
      img.onload = () => {
        const canvas = document.createElement("canvas");
        const scale = maxWidth / Math.max(img.width, img.height);
        const width = scale < 1 ? Math.round(img.width * scale) : img.width;
        const height = scale < 1 ? Math.round(img.height * scale) : img.height;
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext("2d");
        if (ctx) {
          ctx.drawImage(img, 0, 0, width, height);
          resolve(canvas.toDataURL("image/jpeg", quality));
        } else {
          resolve(String(e.target?.result || ""));
        }
      };
      img.onerror = () => resolve(String(e.target?.result || ""));
      img.src = String(e.target?.result || "");
    };
    reader.onerror = () => resolve("");
    reader.readAsDataURL(file);
  });

const compactStoreForLocalBackup = (source: DataStore): DataStore =>
  Object.fromEntries(
    ENTITY_IDS.map((entity) => [
      entity,
      (source[entity] || []).map((record) => {
        const compact = { ...record };
        if (entity === "workshops" && compact.attachments) {
          compact.attachments = compactAttachmentsForLocalBackup(compact.attachments);
        }
        return compact;
      }),
    ]),
  ) as DataStore;

const nowIso = () => new Date().toISOString();
const uid = () => `${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;

const initialsOf = (name: string) =>
  (name || "")
    .trim()
    .split(/\s+/)
    .slice(0, 2)
    .map((part) => part[0] || "")
    .join("")
    .toUpperCase();

function StudentPhoto({
  student,
  fallback,
  alt = "",
  fit = "cover",
}: {
  student: DataRecord;
  sizes?: string;
  fallback: React.ReactNode;
  alt?: string;
  fit?: "cover" | "contain";
}) {
  const [hasError, setHasError] = useState(false);
  const src =
    (typeof student.profilePhoto === "string" ? student.profilePhoto : "") ||
    (typeof student.photo === "string" ? student.photo : "") ||
    (typeof student.avatar === "string" ? student.avatar : "") ||
    (typeof student.image === "string" ? student.image : "") ||
    (typeof student.foto === "string" ? student.foto : "") ||
    (typeof student.picture === "string" ? student.picture : "") ||
    "";

  useEffect(() => {
    setHasError(false);
  }, [src]);

  if (!src || hasError) return <>{fallback}</>;

  return (
    <img
      src={src}
      alt={alt || (typeof student.fullName === "string" ? student.fullName : "Foto del estudiante")}
      onError={() => setHasError(true)}
      className={`absolute inset-0 h-full w-full ${
        fit === "contain" ? "object-contain object-center" : "object-cover object-center"
      }`}
    />
  );
}

type TizaSelectOption = string | { value: string; label: string; keywords?: string[] };

const normalize = (value: string) =>
  value
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, " ")
    .trim();

const getCleanRecordTitle = (rec: DataRecord): string => {
  const explicitTitle = (rec.title || "").trim();
  if (explicitTitle && explicitTitle.length < 90 && !explicitTitle.includes("\n")) {
    return explicitTitle;
  }
  const explicitReason = (rec.reason || "").trim();
  if (explicitReason && explicitReason.length < 90 && !explicitReason.includes("\n")) {
    return explicitReason;
  }

  const typeTag = rec.meetingType || rec.category || rec.type || "Entrevista / Registro";
  const studentTag = rec.student || rec.relatedStudents || rec.relatedTo || "";
  const courseTag = rec.course || rec.cycle || "";

  if (studentTag) {
    return `${typeTag} · ${studentTag}${courseTag ? ` (${courseTag})` : ""}`;
  }
  if (courseTag) {
    return `${typeTag} · ${courseTag}`;
  }

  const rawText = explicitTitle || explicitReason || rec.topic || rec.description || "";
  const firstLine = rawText.split("\n")[0].trim();
  if (firstLine.length > 5 && firstLine.length <= 85) return firstLine;
  return `${typeTag}${firstLine ? ` · ${firstLine.slice(0, 75)}...` : ""}`;
};

const parseStructuredInterviewText = (rawText: string | undefined) => {
  if (!rawText) return { isStructured: false, cleanBody: "" };
  const text = rawText.trim();

  const isFormTemplate =
    text.includes("Motivo de entrevista") ||
    text.includes("Aspectos a tratar") ||
    text.includes("Nombre entrevistador") ||
    text.includes("Nombre Alumno") ||
    text.includes("ENTREVISTA ALUMNO");

  if (!isFormTemplate) return { isStructured: false, cleanBody: text };

  const extractVal = (pattern: RegExp) => {
    const m = text.match(pattern);
    return m ? m[1].trim() : undefined;
  };

  const alumnoName = extractVal(/Nombre Alumno\s*\n+([^\n]+)/i);
  const run = extractVal(/(?:RUN:?\s*\n*)?([0-9\.\-kK]{7,12})/i);
  const entrevistador = extractVal(/Nombre entrevistador\s*\n+([^\n]+)/i);
  const curso = extractVal(/Curso\s*\n+([^\n]+)/i);
  const hora = extractVal(/Hora\s*\n+([^\n]+)/i);
  const fecha = extractVal(/Fecha\s*\n+([^\n]+)/i);
  const acompaniantes = extractVal(/Acompañan en la entrevista\s*\n+([^\n]+)/i);

  const motivoMatch = text.match(/Motivo de entrevista\s*\n+([\s\S]*?)(?=Aspectos a tratar|Acuerdos|Compromisos|$)/i);
  const motivo = motivoMatch ? motivoMatch[1].trim() : undefined;

  const aspectosMatch = text.match(/Aspectos a tratar(?: con el alumno)?\s*\n+([\s\S]*?)(?=Acuerdos|Compromisos|$)/i);
  const aspectos = aspectosMatch ? aspectosMatch[1].trim() : undefined;

  const acuerdosMatch = text.match(/Acuerdos(?: y compromisos)?\s*\n+([\s\S]*?)$/i);
  const acuerdosText = acuerdosMatch ? acuerdosMatch[1].trim() : undefined;

  const hasExtractedSections = Boolean(motivo || aspectos || hora || entrevistador || run);

  const cleanBodyParts = [motivo, aspectos, acuerdosText].filter(Boolean);
  const cleanBody = cleanBodyParts.length > 0 ? cleanBodyParts.join("\n\n") : text;

  return {
    isStructured: hasExtractedSections,
    alumnoName,
    run,
    entrevistador,
    curso,
    hora,
    fecha,
    acompaniantes,
    motivo,
    aspectos,
    acuerdosText,
    cleanBody,
  };
};

const cleanRecordBodyText = (rawText: string | undefined): string => {
  if (!rawText) return "";
  const parsed = parseStructuredInterviewText(rawText);
  if (parsed.isStructured) return parsed.cleanBody;

  let text = rawText.trim();
  if (text.includes("ENTREVISTA ALUMNO") || text.includes("DIRECCIÓN") || text.includes("COORDINACIÓN CICLO")) {
    const lines = text.split("\n").map((l) => l.trim());
    const cleanLines = lines.filter((line) => {
      if (!line) return false;
      if (line.match(/^(ENTREVISTA ALUMNO|DIRECCIÓN|COORDINACIÓN CICLO|CONVIVENCIA ESCOLAR|INSPECTORÍA|PROFESOR JEFE|PROFESOR ASIGNATURA|EQUIPO D\. ESTUDIANTE|PIE|PASTORAL|OTRO|Orientador primer ciclo|RUN:)$/i)) {
        return false;
      }
      return true;
    });
    text = cleanLines.join("\n");
  }
  return text.trim();
};

const textDistance = (left: string, right: string) => {
  const previous = Array.from({ length: right.length + 1 }, (_, index) => index);
  for (let leftIndex = 1; leftIndex <= left.length; leftIndex += 1) {
    const current = [leftIndex];
    for (let rightIndex = 1; rightIndex <= right.length; rightIndex += 1) {
      current[rightIndex] = Math.min(
        current[rightIndex - 1] + 1,
        previous[rightIndex] + 1,
        previous[rightIndex - 1] + (left[leftIndex - 1] === right[rightIndex - 1] ? 0 : 1),
      );
    }
    previous.splice(0, previous.length, ...current);
  }
  return previous[right.length];
};

const fuzzySearchScore = (query: string, candidate: string) => {
  const normalizedQuery = normalize(query);
  const normalizedCandidate = normalize(candidate);
  if (!normalizedQuery || !normalizedCandidate) return 0;
  if (normalizedQuery === normalizedCandidate) return 1000;
  if (normalizedCandidate.startsWith(normalizedQuery)) return 920 - Math.min(80, normalizedCandidate.length - normalizedQuery.length);
  if (normalizedCandidate.includes(normalizedQuery)) return 860 - Math.min(80, normalizedCandidate.length - normalizedQuery.length);

  const queryTokens = normalizedQuery.split(" ");
  const candidateTokens = normalizedCandidate.split(" ");
  const matchingTokens = queryTokens.filter((queryToken) =>
    candidateTokens.some((candidateToken) => candidateToken.startsWith(queryToken) || candidateToken.includes(queryToken)),
  );
  if (matchingTokens.length === queryTokens.length) return 800 + matchingTokens.length * 5;

  const queryCompact = normalizedQuery.replace(/\s/g, "");
  const candidateCompact = normalizedCandidate.replace(/\s/g, "");
  if (candidateCompact.startsWith(queryCompact)) return 780;
  if (candidateCompact.includes(queryCompact)) return 740;

  let queryIndex = 0;
  for (const character of candidateCompact) {
    if (character === queryCompact[queryIndex]) queryIndex += 1;
    if (queryIndex === queryCompact.length) break;
  }
  if (queryIndex === queryCompact.length) return 520 + Math.round((queryCompact.length / candidateCompact.length) * 100);

  const similarities = queryTokens.flatMap((queryToken) => candidateTokens.map((candidateToken) => {
    const longest = Math.max(queryToken.length, candidateToken.length);
    return longest ? 1 - textDistance(queryToken, candidateToken) / longest : 0;
  }));
  const bestSimilarity = Math.max(0, ...similarities);
  return bestSimilarity >= 0.58 ? 400 + Math.round(bestSimilarity * 100) : 0;
};

// Campo de fecha que siempre muestra DD/MM/AAAA (el input nativo depende del
// idioma del navegador); el input date transparente encima abre el calendario.
function TizaDateInput({
  value,
  onChange,
  disabled = false,
  className = "",
  fieldClassName = "rounded-md border border-slate-200 bg-white px-2.5 py-2 text-sm",
}: {
  value: string;
  onChange: (value: string) => void;
  disabled?: boolean;
  className?: string;
  fieldClassName?: string;
}) {
  const inputRef = useRef<HTMLInputElement>(null);
  const match = String(value || "").match(/^(\d{4})-(\d{2})-(\d{2})/);
  const display = match ? `${match[3]}/${match[2]}/${match[1]}` : "";
  return (
    <div className={`relative ${className}`}>
      <div
        aria-hidden
        className={`pointer-events-none flex w-full items-center justify-between gap-2 tabular-nums transition ${fieldClassName} ${disabled ? "!bg-slate-100 text-slate-500" : "text-slate-800"}`}
      >
        <span className={display ? "" : "text-slate-400"}>{display || "dd/mm/aaaa"}</span>
        <CalendarDays className="h-4 w-4 shrink-0 text-slate-400" />
      </div>
      <input
        ref={inputRef}
        type="date"
        value={value}
        disabled={disabled}
        onChange={(event) => onChange(event.target.value)}
        onClick={() => { try { inputRef.current?.showPicker(); } catch { /* navegador sin showPicker: usa el control nativo */ } }}
        className="absolute inset-0 h-full w-full cursor-pointer opacity-0 disabled:cursor-not-allowed"
      />
    </div>
  );
}

function TizaSelect({
  value,
  options,
  onChange,
  placeholder = "Seleccionar",
  disabled = false,
  className = "",
  buttonClassName = "",
  menuClassName = "",
  searchable = false,
  searchPlaceholder = "Escribe para buscar...",
}: {
  value: string;
  options: TizaSelectOption[];
  onChange: (value: string) => void;
  placeholder?: string;
  disabled?: boolean;
  className?: string;
  buttonClassName?: string;
  menuClassName?: string;
  searchable?: boolean;
  searchPlaceholder?: string;
}) {
  const [open, setOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [menuPosition, setMenuPosition] = useState<React.CSSProperties>({});
  const rootRef = useRef<HTMLDivElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);
  const normalizedOptions = options.map((option) =>
    typeof option === "string" ? { value: option, label: option, keywords: [] } : { ...option, keywords: option.keywords || [] },
  );
  const selected = normalizedOptions.find((option) => option.value === value);
  const normalizedQuery = normalize(searchQuery);
  const visibleOptions = searchable && normalizedQuery
    ? normalizedOptions
        .map((option) => ({
          ...option,
          searchScore: Math.max(
            fuzzySearchScore(searchQuery, option.label),
            fuzzySearchScore(searchQuery, option.value),
            ...option.keywords.map((keyword) => fuzzySearchScore(searchQuery, keyword)),
          ),
        }))
        .filter((option) => option.searchScore > 0)
        .sort((left, right) => right.searchScore - left.searchScore || left.label.localeCompare(right.label, "es"))
    : normalizedOptions.map((option) => ({ ...option, searchScore: 0 }));
  // Si buttonClassName trae su propio fondo (p. ej. el tono del estado), no se
  // aplican los colores por defecto para que el tinte personalizado se vea.
  const hasCustomTone = /(^|\s)bg-/.test(buttonClassName);

  useEffect(() => {
    if (!open) return;
    const closeOnOutside = (event: PointerEvent) => {
      if (!rootRef.current?.contains(event.target as Node) && !menuRef.current?.contains(event.target as Node)) {
        setOpen(false);
        setSearchQuery("");
      }
    };
    const closeOnEscape = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setOpen(false);
        setSearchQuery("");
      }
    };
    document.addEventListener("pointerdown", closeOnOutside);
    document.addEventListener("keydown", closeOnEscape);
    return () => {
      document.removeEventListener("pointerdown", closeOnOutside);
      document.removeEventListener("keydown", closeOnEscape);
    };
  }, [open]);

  useEffect(() => {
    if (!open) return;
    const positionMenu = () => {
      const rect = rootRef.current?.getBoundingClientRect();
      if (!rect) return;
      const estimatedHeight = searchable ? 300 : Math.min(260, normalizedOptions.length * 42 + 16);
      const roomBelow = window.innerHeight - rect.bottom;
      const openUp = roomBelow < Math.min(estimatedHeight, 220) && rect.top > roomBelow;
      setMenuPosition({
        position: "fixed",
        left: Math.max(8, Math.min(rect.left, window.innerWidth - Math.max(rect.width, searchable ? 320 : rect.width) - 8)),
        top: openUp ? "auto" : rect.bottom + 8,
        bottom: openUp ? window.innerHeight - rect.top + 8 : "auto",
        width: searchable ? `min(320px, calc(100vw - 1rem))` : rect.width,
      });
    };
    positionMenu();
    window.addEventListener("resize", positionMenu);
    window.addEventListener("scroll", positionMenu, true);
    return () => {
      window.removeEventListener("resize", positionMenu);
      window.removeEventListener("scroll", positionMenu, true);
    };
  }, [open, searchable, normalizedOptions.length]);

  useEffect(() => {
    if (!open || !searchable) return;
    const frame = requestAnimationFrame(() => searchInputRef.current?.focus());
    return () => cancelAnimationFrame(frame);
  }, [open, searchable]);

  return (
    <div ref={rootRef} className={`relative ${className}`}>
      <button
        type="button"
        disabled={disabled}
        aria-haspopup="listbox"
        aria-expanded={open}
        onClick={() => {
          setSearchQuery("");
          startAfterNextPaint(() => setOpen((current) => !current));
        }}
        className={`inline-flex w-full items-center justify-between gap-2 rounded-lg border px-3 py-2 text-left text-sm outline-none transition focus:border-cyan-600 focus:ring-4 focus:ring-cyan-100 disabled:bg-slate-100 disabled:text-slate-500 ${hasCustomTone ? "border-transparent" : "border-slate-200 bg-white text-slate-800 hover:border-cyan-400"} ${buttonClassName}`}
      >
        <span className="truncate">{selected?.label || placeholder}</span>
        <ChevronDown className={`h-4 w-4 shrink-0 text-slate-400 transition ${open ? "rotate-180" : ""}`} />
      </button>
      {open && typeof document !== "undefined" ? createPortal(
        <div
          ref={menuRef}
          className={`z-[120] overflow-hidden rounded-lg border border-slate-200 bg-white text-sm shadow-[0_18px_45px_-12px_rgba(15,23,42,0.28)] ring-1 ring-slate-900/5 ${menuClassName}`}
          style={menuPosition}
        >
          {searchable ? (
            <div className="flex h-11 items-center gap-2.5 border-b border-slate-100 bg-slate-50/80 px-3 transition focus-within:bg-white">
              <Search className="h-4 w-4 shrink-0 text-cyan-700" />
              <input
                ref={searchInputRef}
                value={searchQuery}
                onChange={(event) => setSearchQuery(event.target.value)}
                onKeyDown={(event) => {
                  if (event.key !== "Enter" || !visibleOptions[0]) return;
                  event.preventDefault();
                  setOpen(false);
                  setSearchQuery("");
                  startAfterNextPaint(() => onChange(visibleOptions[0].value));
                }}
                aria-label={searchPlaceholder}
                placeholder={searchPlaceholder}
                className="min-w-0 flex-1 bg-transparent text-sm font-medium text-slate-900 outline-none placeholder:text-slate-400"
              />
              {searchQuery ? (
                <button type="button" onClick={() => setSearchQuery("")} title="Limpiar búsqueda" className="grid h-7 w-7 shrink-0 place-items-center rounded-md text-slate-400 transition hover:bg-slate-100 hover:text-slate-700">
                  <X className="h-3.5 w-3.5" />
                </button>
              ) : null}
            </div>
          ) : null}
          <div role="listbox" className="max-h-60 overflow-y-auto overscroll-contain p-1.5 [scrollbar-gutter:stable]">
            {visibleOptions.map((option, index) => {
              const active = option.value === value;
              return (
                <button
                  key={option.value}
                  type="button"
                  role="option"
                  aria-selected={active}
                  onClick={() => {
                    setOpen(false);
                    setSearchQuery("");
                    startAfterNextPaint(() => onChange(option.value));
                  }}
                  className={`flex min-h-9 w-full items-center justify-between gap-3 rounded-md px-3 py-2 text-left text-sm font-medium transition ${
                    active ? "bg-cyan-50 text-cyan-900" : "text-slate-700 hover:bg-slate-50 hover:text-slate-950"
                  }`}
                >
                  <span className="truncate">{option.label}</span>
                  {active ? <Check className="h-4 w-4 shrink-0 text-cyan-700" /> : searchable && normalizedQuery && index === 0 ? <span className="shrink-0 rounded-md bg-cyan-50 px-1.5 py-0.5 text-[10px] font-semibold text-cyan-700">Sugerida</span> : null}
                </button>
              );
            })}
            {visibleOptions.length === 0 ? (
              <div className="px-3 py-6 text-center">
                <p className="text-sm font-semibold text-slate-700">Sin coincidencias</p>
                <p className="mt-1 text-xs text-slate-400">Prueba otra palabra o abreviación.</p>
              </div>
            ) : null}
          </div>
        </div>,
        document.body,
      ) : null}
    </div>
  );
}

const avatarTone = (seed: string) => {
  const palette = [
    "from-sky-500 to-blue-600",
    "from-emerald-500 to-teal-600",
    "from-amber-500 to-orange-600",
    "from-violet-500 to-purple-600",
    "from-rose-500 to-pink-600",
    "from-cyan-500 to-blue-500",
    "from-lime-500 to-emerald-600",
    "from-fuchsia-500 to-purple-600",
  ];
  let hash = 0;
  for (let i = 0; i < seed.length; i += 1) hash = (hash * 31 + seed.charCodeAt(i)) >>> 0;
  return palette[hash % palette.length];
};

const isValidImportedStudentName = (value: string) => {
  const text = String(value || "").trim();
  if (!text || /@/.test(text)) return false;
  const words = text.split(/\s+/).filter((word) => /[a-záéíóúñ]/i.test(word));
  return words.length >= 2;
};

