// ---- Sincronización fecha ↔ semana del plan de orientación ----
const parseOrientationWeekRange = (week: string) => {
  const match = week.match(/(\d{2})\/(\d{2})\s+al\s+(\d{2})\/(\d{2})/);
  if (!match) return null;
  const [, startDay, startMonth, endDay, endMonth] = match;
  return { start: `2026-${startMonth}-${startDay}`, end: `2026-${endMonth}-${endDay}` };
};

const orientationConfigForDate = (dateISO: string) =>
  ORIENTATION_FIRST_CYCLE_CONFIG.find((config) => {
    const range = parseOrientationWeekRange(config.week);
    return range && dateISO >= range.start && dateISO <= range.end;
  });

const orientationWeekNumber = (week: string) => week.match(/Semana\s+(\d+)/i)?.[1] || "";

const canonicalCourseKey = (value: string | undefined): string => {
  if (!value) return "";
  let s = normalize(value).toLowerCase().trim();

  // Words & Ordinals
  s = s
    .replace(/\bprimero\b/g, "1")
    .replace(/\bsegundo\b/g, "2")
    .replace(/\btercero\b/g, "3")
    .replace(/\bcuarto\b/g, "4")
    .replace(/\bquinto\b/g, "5")
    .replace(/\bsexto\b/g, "6")
    .replace(/\bseptimo\b/g, "7")
    .replace(/\boctavo\b/g, "8")
    .replace(/(\d+)(st|nd|rd|th|ro|er|era|do|to|vo|mo|no|°|º|\^)/gi, "$1");

  // Kindergarten & Prekinder
  s = s
    .replace(/\bpre\s*kinder\b/gi, "prekinder")
    .replace(/\bpre-kinder\b/gi, "prekinder")
    .replace(/\bpk\s*([a-c])\b/gi, "prekinder $1")
    .replace(/\bpk([a-c])\b/gi, "prekinder $1")
    .replace(/\bkinder\b/gi, "kinder")
    .replace(/\bk\s*([a-c])\b/gi, "kinder $1")
    .replace(/\bk([a-c])\b/gi, "kinder $1");

  // Roman numerals for media (IV°A, III°B, II°A, I°B)
  s = s
    .replace(/\biv\s*°?\s*medio\s*([a-c])?\b/gi, "4 medio $1")
    .replace(/\biii\s*°?\s*medio\s*([a-c])?\b/gi, "3 medio $1")
    .replace(/\bii\s*°?\s*medio\s*([a-c])?\b/gi, "2 medio $1")
    .replace(/\bi\s*°?\s*medio\s*([a-c])?\b/gi, "1 medio $1")
    .replace(/\biv\s*°?\s*([a-c])\b/gi, "4 medio $1")
    .replace(/\biii\s*°?\s*([a-c])\b/gi, "3 medio $1")
    .replace(/\bii\s*°?\s*([a-c])\b/gi, "2 medio $1")
    .replace(/\bi\s*°?\s*([a-c])\b/gi, "1 medio $1");

  // Short media notation: 1MA, 2MB, 3MA, 4MB
  s = s.replace(/\b([1-4])\s*m\s*([a-c])\b/gi, "$1 medio $2");

  // Short basic notation: 1A, 1 A, 1°A -> 1 basico a (only if not already containing medio)
  if (!s.includes("medio")) {
    s = s.replace(/\b([1-8])\s*([a-c])\b/gi, "$1 basico $2");
  }

  s = s.replace(/[^a-z0-9\s]/gi, " ").replace(/\s+/g, " ").trim();
  return s;
};

// Los archivos de horario nombran los cursos con palabras completas
// ("PRIMERO MEDIO A"), mientras la interfaz usa "I° Medio A". Esta clave
// permite relacionarlos sin depender de cómo fue escrito el nombre original.
const schoolScheduleCourseKey = (value: string) =>
  canonicalCourseKey(value)
    .replace(/[°º]/g, "")
    .replace(/\bpre\s*kinder\b/g, "prekinder")
    .replace(/^iv\s+medio\b/g, "4 medio")
    .replace(/^iii\s+medio\b/g, "3 medio")
    .replace(/^ii\s+medio\b/g, "2 medio")
    .replace(/^i\s+medio\b/g, "1 medio")
    .replace(/\s+/g, " ")
    .trim();

// Clave compacta compartida por las tablas del PDF (PK°A, 1°A, II°B)
// y los nombres completos de la app (Prekínder A, 1° Básico A, II° Medio B).
const classroomTeamCourseKey = (value: string) => {
  let text = normalize(value).replace(/\bpre\s+kinder\b/g, "prekinder");
  const isHighSchool = /\bmedio\b/.test(text);
  text = text
    .replace(/\bprimero\b/g, "1")
    .replace(/\bsegundo\b/g, "2")
    .replace(/\btercero\b/g, "3")
    .replace(/\bcuarto\b/g, "4")
    .replace(/\bquinto\b/g, "5")
    .replace(/\bsexto\b/g, "6")
    .replace(/\bseptimo\b/g, "7")
    .replace(/\boctavo\b/g, "8")
    .replace(/\b(?:basico|medio)\b/g, "")
    .replace(/\s+/g, "");
  const section = text.match(/([abc])$/)?.[1] || "";
  if (/^(?:prekinder|pk)/.test(text)) return `pk${section}`;
  if (/^(?:kinder|k)/.test(text)) return `k${section}`;
  if (isHighSchool || /^(?:iv|iii|ii|i)/.test(text)) {
    const level = /^iv/.test(text) ? "4" : /^iii/.test(text) ? "3" : /^ii/.test(text) ? "2" : /^i/.test(text) ? "1" : text.match(/^([1-4])/)?.[1];
    return level ? `m${level}${section}` : "";
  }
  const level = text.match(/^([1-8])/)?.[1];
  return level ? `b${level}${section}` : "";
};

