const feedbackTeacherDisplayName = (name: string) => {
  const trimmed = name.trim();
  if (!trimmed || trimmed !== trimmed.toLocaleUpperCase("es")) return trimmed;
  return trimmed
    .toLocaleLowerCase("es")
    .replace(/(^|[\s-])([a-záéíóúüñ])/g, (_, separator: string, letter: string) => `${separator}${letter.toLocaleUpperCase("es")}`);
};

const FEEDBACK_TEACHER_OPTIONS: FeedbackTeacherOption[] = (() => {
  const byEmail = new Map<string, FeedbackTeacherOption>();
  FIRST_CYCLE_COURSES.forEach((course) => {
    const member = firstCycleHeadTeachers[classroomTeamCourseKey(course)];
    if (!member) return;
    const email = String(member?.email || "").trim().toLowerCase();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return;
    if (!byEmail.has(email)) {
      byEmail.set(email, {
        name: feedbackTeacherDisplayName(member.name),
        email,
        role: "Profesor/a jefe de primer ciclo",
        headship: course,
      });
    }
  });
  return [
    FEEDBACK_TEST_TEACHER,
    ...Array.from(byEmail.values()).sort((a, b) => a.name.localeCompare(b.name, "es", { sensitivity: "base" })),
  ];
})();

// Próxima fecha en que le toca orientación a un curso, después de una fecha dada.
const nextSlotDateForCourse = (course: string, afterISO: string) => {
  const slot = ORIENTATION_WEEKLY_SLOTS.find((item) => normalize(item.course) === normalize(course));
  const [year, month, day] = afterISO.split("-").map(Number);
  const pad = (value: number) => String(value).padStart(2, "0");
  if (!year || !month || !day) return afterISO;
  const base = new Date(year, month - 1, day);
  for (let offset = 1; offset <= 28; offset += 1) {
    const candidate = new Date(base.getFullYear(), base.getMonth(), base.getDate() + offset);
    const weekday = candidate.getDay();
    if (slot ? weekday === slot.day : offset === 7) {
      return `${candidate.getFullYear()}-${pad(candidate.getMonth() + 1)}-${pad(candidate.getDate())}`;
    }
  }
  return afterISO;
};

const formatDateCL = (iso: string) => {
  const [year, month, day] = iso.split("-");
  return year && month && day ? `${day}/${month}/${year}` : iso;
};

const localISODate = (date = new Date()) => {
  const pad = (value: number) => String(value).padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
};

// Fecha de nacimiento a Date. La nómina la trae como DD/MM/AAAA y el selector
// de la app la guarda como AAAA-MM-DD.
const parseBirthDate = (value: string | undefined) => {
  const text = String(value || "").trim();
  if (!text) return null;
  const dmy = text.match(/^(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{4})$/);
  const iso = text.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  const [year, month, day] = dmy
    ? [Number(dmy[3]), Number(dmy[2]), Number(dmy[1])]
    : iso ? [Number(iso[1]), Number(iso[2]), Number(iso[3])] : [0, 0, 0];
  if (!year || !month || !day) return null;
  const date = new Date(year, month - 1, day);
  return Number.isNaN(date.getTime()) ? null : date;
};

// Edad cumplida al día de la consulta.
const ageFromBirthDate = (value: string | undefined, today = new Date()) => {
  const birth = parseBirthDate(value);
  if (!birth) return null;
  let age = today.getFullYear() - birth.getFullYear();
  const monthDiff = today.getMonth() - birth.getMonth();
  if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < birth.getDate())) age -= 1;
  return age >= 0 && age < 120 ? age : null;
};

const birthdayIsToday = (value: string | undefined, today = new Date()) => {
  const birth = parseBirthDate(value);
  return Boolean(birth) && birth!.getDate() === today.getDate() && birth!.getMonth() === today.getMonth();
};

type OrientationPeriodFilter = "today" | "all" | "this-week" | "next-week" | "upcoming" | "history";

const orientationWeekWindows = (todayISO: string) => {
  const [year, month, day] = todayISO.split("-").map(Number);
  const base = new Date(year, month - 1, day || 1, 12);
  const weekday = base.getDay();
  const mondayOffset = weekday === 0 ? -6 : 1 - weekday;
  const pad = (value: number) => String(value).padStart(2, "0");
  const addDays = (offset: number) => {
    const date = new Date(base.getFullYear(), base.getMonth(), base.getDate() + mondayOffset + offset, 12);
    return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
  };
  return {
    thisWeekStart: addDays(0),
    thisWeekEnd: addDays(6),
    nextWeekStart: addDays(7),
    nextWeekEnd: addDays(13),
  };
};

const orientationDateMatchesPeriod = (
  dateValue: string | undefined,
  period: OrientationPeriodFilter,
  todayISO: string,
  windows: ReturnType<typeof orientationWeekWindows>,
) => {
  const date = (dateValue || "").slice(0, 10);
  if (period === "all") return true;
  if (!date) return false;
  if (period === "today") return date === todayISO;
  if (period === "this-week") return date >= windows.thisWeekStart && date <= windows.thisWeekEnd;
  if (period === "next-week") return date >= windows.nextWeekStart && date <= windows.nextWeekEnd;
  if (period === "upcoming") return date >= todayISO;
  return date < todayISO;
};

// Fecha que corresponde a un curso dentro de una semana, según el horario fijo.
const scheduledDateForCourse = (course: string, weekStartISO: string, schedule: OrientationWeeklySlot[] = ORIENTATION_WEEKLY_SLOTS) => {
  const slot = schedule.find((item) => normalize(item.course) === normalize(course));
  const [year, month, day] = weekStartISO.split("-").map(Number);
  if (!year || !month || !day) return weekStartISO;
  const date = new Date(year, month - 1, day + (slot ? slot.day - 1 : 0));
  const pad = (value: number) => String(value).padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
};

// Hora de la clase según el horario semanal fijo de orientación 2026.
const orientationClassTime = (course: string | undefined, schedule: OrientationWeeklySlot[] = ORIENTATION_WEEKLY_SLOTS) => {
  const slot = schedule.find((item) => normalize(item.course) === normalize(course || ""));
  return slot ? `${slot.start} – ${slot.end}` : "";
};

const orientationClassStartMinutes = (course: string | undefined, schedule: OrientationWeeklySlot[] = ORIENTATION_WEEKLY_SLOTS) => {
  const slot = schedule.find((item) => normalize(item.course) === normalize(course || ""));
  if (!slot) return Number.MAX_SAFE_INTEGER;
  const [hours, minutes] = slot.start.split(":").map(Number);
  return Number.isFinite(hours) && Number.isFinite(minutes) ? hours * 60 + minutes : Number.MAX_SAFE_INTEGER;
};

const formatOrientationDate = (value: string | undefined) => {
  if (!value) return "Sin fecha";
  const match = value.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (!match) return value;
  const [, year, month, day] = match;
  const date = new Date(Number(year), Number(month) - 1, Number(day));
  const weekdays = ["Dom", "Lun", "Mar", "Mié", "Jue", "Vie", "Sáb"];
  const months = ["Ene", "Feb", "Mar", "Abr", "May", "Jun", "Jul", "Ago", "Sep", "Oct", "Nov", "Dic"];
  return `${weekdays[date.getDay()]}, ${day} ${months[Number(month) - 1]} ${year}`;
};

