type TizaAppConfiguration = {
  orientationActions: string[];
  orientationSchedule: OrientationWeeklySlot[];
  courseSchedule: CourseScheduleEntry[];
  staffSchedule: StaffScheduleEntry[];
};

const defaultAppConfiguration = (): TizaAppConfiguration => ({
  orientationActions: [...orientationActionColumns],
  orientationSchedule: ORIENTATION_WEEKLY_SLOTS.map((slot) => ({ ...slot })),
  courseSchedule: [],
  staffSchedule: [],
});

// Mantiene vigente el horario institucional corregido aunque el perfil todavía
// conserve una copia anterior de la configuración semanal.
const applyOrientationScheduleCorrections = (schedule: OrientationWeeklySlot[]) => {
  const corrected = schedule.map((slot) => (
    normalize(slot.owner) === normalize("Gustavo Caro") && normalize(slot.course) === normalize("4° Básico A")
      ? { ...slot, day: 1 as const, dayName: "Lunes" as const, start: "14:15", end: "14:55" }
      : slot
  ));
  // Las configuraciones guardadas antes de incorporar un curso pueden quedar
  // incompletas. Se agregan únicamente los bloques oficiales ausentes y se
  // conservan intactos los horarios personalizados que sí existen.
  ORIENTATION_WEEKLY_SLOTS.forEach((officialSlot) => {
    const exists = corrected.some((slot) =>
      normalize(slot.owner) === normalize(officialSlot.owner) && normalize(slot.course) === normalize(officialSlot.course)
    );
    if (!exists) corrected.push({ ...officialSlot });
  });
  return corrected;
};

const parseAppConfiguration = (value: string | undefined): TizaAppConfiguration => {
  const defaults = defaultAppConfiguration();
  if (!value) return defaults;
  try {
    const parsed = JSON.parse(value) as Partial<TizaAppConfiguration>;
    const actions = Array.isArray(parsed.orientationActions)
      ? parsed.orientationActions.map(String).map((item) => item.trim()).filter(Boolean)
      : [];
    const schedule = Array.isArray(parsed.orientationSchedule)
      ? parsed.orientationSchedule.filter((slot): slot is OrientationWeeklySlot => Boolean(
          slot && Number(slot.day) >= 1 && Number(slot.day) <= 5 && slot.course && slot.start && slot.end && slot.owner,
        ))
      : [];
    const courseSchedule = Array.isArray(parsed.courseSchedule)
      ? parsed.courseSchedule.filter((slot): slot is CourseScheduleEntry => Boolean(slot?.course && slot?.day && slot?.startTime && slot?.endTime))
      : [];
    const staffSchedule = Array.isArray(parsed.staffSchedule)
      ? parsed.staffSchedule.filter((slot): slot is StaffScheduleEntry => Boolean(slot?.staffName && slot?.day && slot?.startTime && slot?.endTime))
      : [];
    return {
      orientationActions: actions.length ? Array.from(new Set(actions)) : defaults.orientationActions,
      orientationSchedule: applyOrientationScheduleCorrections(schedule.length ? schedule : defaults.orientationSchedule),
      courseSchedule,
      staffSchedule,
    };
  } catch {
    return defaults;
  }
};

const courseSearchKeywords = (course: string) => {
  const normalizedCourse = normalize(course);
  const letter = normalizedCourse.match(/\b([a-z])$/)?.[1] || "";
  if (normalizedCourse.startsWith("prekinder")) {
    return [`pk${letter}`, `pk ${letter}`, `pre k ${letter}`, `pre kinder ${letter}`, `preka ${letter}`];
  }
  if (normalizedCourse.startsWith("kinder")) {
    return [`k${letter}`, `k ${letter}`, `kinder ${letter}`];
  }
  const basicCourse = normalizedCourse.match(/^(\d+)\s+basico\s+([a-z])$/);
  if (!basicCourse) return [];
  const [, level, section] = basicCourse;
  const levelNames: Record<string, string> = {
    "1": "primero",
    "2": "segundo",
    "3": "tercero",
    "4": "cuarto",
    "5": "quinto",
    "6": "sexto",
    "7": "septimo",
    "8": "octavo",
  };
  return [`${level}${section}`, `${level} ${section}`, `${level} basico ${section}`, `${levelNames[level] || level} ${section}`];
};

