const buildDataContext = (store: DataStore): string => {
  const lines: string[] = [];
  lines.push(`Total estudiantes: ${store.students.length}`);
  lines.push(`Cursos guardados: ${store.courses.length}`);
  lines.push(`Funcionarios/base institucional: ${store.personnel.length}`);
  lines.push(`Estudiantes marcados PIE/NEE: ${store.students.filter((student) => /pie|nee|diferencial/i.test(`${student.tags || ""} ${student.supportNeeds || ""} ${student.observations || ""}`)).length}`);

  // Casos
  const casesTotal = store.cases.length;
  const open = store.cases.filter((c) => /abierto|seguimiento|activ/i.test(c.status || "")).length;
  const closed = store.cases.filter((c) => /cerrad/i.test(c.status || "")).length;
  const critical = store.cases.filter((c) => /critic|alta/i.test(c.priority || "")).length;
  lines.push(`Casos: ${casesTotal} (abiertos/seguimiento: ${open}, cerrados: ${closed}, alta/crítica: ${critical})`);

  const byCategory = new Map<string, number>();
  store.cases.forEach((c) => {
    const k = c.category || "Sin categoría";
    byCategory.set(k, (byCategory.get(k) || 0) + 1);
  });
  const catLine = Array.from(byCategory.entries()).sort((a, b) => b[1] - a[1]).slice(0, 8).map(([k, v]) => `${k}: ${v}`).join(", ");
  if (catLine) lines.push(`  Por categoría: ${catLine}`);

  const recentCases = [...store.cases].sort((a, b) => (b.updatedAt || "").localeCompare(a.updatedAt || "")).slice(0, 20);
  if (recentCases.length > 0) {
    lines.push(`\nÚLTIMOS ${recentCases.length} CASOS (más recientes primero):`);
    recentCases.forEach((c) => {
      const intCount = (() => { try { return Array.isArray(JSON.parse(c.interventions || "[]")) ? JSON.parse(c.interventions || "[]").length : 0; } catch { return 0; } })();
      lines.push(`- [${c.status || "?"}] ${c.title || "Sin título"} · ${c.student || ""} (${c.course || "?"}) · prioridad ${c.priority || "?"} · ${intCount} intervenciones`);
    });
  }

  // Entrevistas
  const today = new Date().toISOString().slice(0, 10);
  const upcoming = store.interviews.filter((r) => (r.date || "") >= today);
  lines.push(`\nEntrevistas totales: ${store.interviews.length} (próximas/hoy: ${upcoming.length})`);
  upcoming.slice(0, 10).forEach((r) => {
    lines.push(`- ${r.date} · ${r.participant || "?"} con ${r.student || "?"} · ${r.reason || ""}`);
  });

  // Bitácoras
  lines.push(`\nBitácoras totales: ${store.logs.length}`);
  const recentLogs = [...store.logs].sort((a, b) => (b.date || "").localeCompare(a.date || "")).slice(0, 10);
  recentLogs.forEach((l) => {
    lines.push(`- ${l.date || "?"} · ${l.type || "?"} · ${l.student || "?"} · ${(l.description || "").slice(0, 100)}`);
  });

  // Protocolos
  const dueSoon = store.protocols.filter((p) => p.dueDate && p.dueDate >= today && p.dueDate <= new Date(Date.now() + 14 * 86400000).toISOString().slice(0, 10) && !/cerrad/i.test(p.status || ""));
  lines.push(`\nProtocolos: ${store.protocols.length} (a vencer en 14 días: ${dueSoon.length})`);
  dueSoon.slice(0, 10).forEach((p) => {
    lines.push(`- ${p.dueDate} · ${p.title} · ${p.student || ""} · ${p.status || ""}`);
  });

  // Orientación
  lines.push(`\nClases de orientación: ${store.orientation.length}`);
  const ownerCounts = new Map<string, number>();
  store.orientation.forEach((o) => {
    const k = o.orientationOwner || "Sin orientador";
    ownerCounts.set(k, (ownerCounts.get(k) || 0) + 1);
  });
  Array.from(ownerCounts.entries()).forEach(([k, v]) => lines.push(`  ${k}: ${v} clases`));

  // Talleres
  lines.push(`\nTalleres totales: ${store.workshops.length}`);
  // Documentos
  lines.push(`Documentos totales: ${store.documents.length}`);

  // Alertas de salud
  const healthAlerts = store.students.filter((s) => (s.healthAlerts || "").trim());
  lines.push(`\nEstudiantes con alerta de salud: ${healthAlerts.length}`);
  healthAlerts.slice(0, 15).forEach((s) => {
    lines.push(`- ${s.fullName} (${s.course}): ${(s.healthAlerts || "").slice(0, 100)}`);
  });

  return lines.join("\n");
};



const isCourseMatch = (courseA: string | undefined, courseB: string | undefined): boolean => {
  if (!courseA || !courseB) return false;
  if (courseA === courseB) return true;
  const keyA = canonicalCourseKey(courseA);
  const keyB = canonicalCourseKey(courseB);
  if (!keyA || !keyB) return false;
  if (keyA === keyB) return true;
  if (keyA.includes(keyB) || keyB.includes(keyA)) return true;
  return false;
};

const courseMatches = (record: DataRecord, courseName: string) => {
  if (!courseName) return false;
  return Object.values(record).some((value) => {
    const valStr = String(value || "");
    return isCourseMatch(valStr, courseName) || normalize(valStr).includes(normalize(courseName));
  });
};

const studentMatches = (record: DataRecord, student: DataRecord) => {
  const studentName = normalize(student.fullName || "");
  const studentRut = normalize(student.rut || "");
  const values = Object.values(record).map((value) => normalize(String(value)));
  return values.some((value) => Boolean(studentName && value.includes(studentName)) || Boolean(studentRut && value.includes(studentRut)));
};

const parseSeatAssignments = (value: string | undefined): string[] => {
  if (!value) return [];
  try {
    const parsed = JSON.parse(value);
    return Array.isArray(parsed) ? parsed.map((item) => String(item || "")) : [];
  } catch {
    return [];
  }
};

const classroomRoles = [
  "Profesor/a jefe",
  "Profesor/a de asignatura",
  "Asistente de aula",
  "Educadora diferencial",
  "Educadora de párvulos",
  "Técnico en párvulos",
  "Inspector/a",
  "Psicóloga",
  "Trabajadora social",
  "Coordinadora de convivencia",
  "Orientador/a",
  "Otro apoyo",
];

const parseClassroomTeam = (value: string | undefined): ClassroomTeamMember[] => {
  if (!value) return [];
  try {
    const parsed = JSON.parse(value);
    if (!Array.isArray(parsed)) return [];
    return parsed.filter((member) => member && typeof member.name === "string" && typeof member.role === "string");
  } catch {
    return [];
  }
};

const classroomRoleFromSubject = (subject: string, course: string) => {
  const normalizedSubject = normalize(subject);
  if (normalizedSubject.includes("tecnico")) {
    return /^(?:pk|k)/.test(classroomTeamCourseKey(course)) ? "Técnico en párvulos" : "Asistente de aula";
  }
  if (/\bpie\b|diferencial/.test(normalizedSubject)) return "Educadora diferencial";
  if (/biblioteca|cra/.test(normalizedSubject)) return "Otro apoyo";
  return subject ? `Profesor/a de ${subject}` : "Profesor/a de asignatura";
};

const officialClassroomTeamForCourse = (course: string): ClassroomTeamMember[] => {
  const seeds = classroomTeamSeedsByCourse.get(classroomTeamCourseKey(course)) || [];
  const headTeacher = headTeacherForCourse(course);
  return seeds.map((member, index) => {
    const memberNameParts = normalize(member.name).split(/\s+/).filter(Boolean);
    const headTeacherNameParts = normalize(headTeacher?.name || "").split(/\s+/).filter(Boolean);
    const hasMatchingName = normalize(member.name) === normalize(headTeacher?.name || "")
      || Boolean(
        memberNameParts.length > 1
        && headTeacherNameParts.length > 1
        && memberNameParts[0]?.[0] === headTeacherNameParts[0]?.[0]
        && memberNameParts.at(-1) === headTeacherNameParts.at(-1),
      );
    const isHeadTeacher = Boolean(
      headTeacher
      && (
        hasMatchingName
        || (member.email && headTeacher.email && normalize(member.email) === normalize(headTeacher.email))
      ),
    );
    return {
      id: `official-team-${classroomTeamCourseKey(course)}-${index}-${normalize(member.email || member.name).replace(/\s+/g, "-")}`,
      name: member.name,
      role: isHeadTeacher ? "Profesor/a jefe" : classroomRoleFromSubject(member.subject, course),
      email: member.email,
      notes: member.subject ? `Asignatura: ${member.subject}` : "",
    };
  });
};

const classroomTeamForCourse = (course: string, record: DataRecord | undefined) => {
  const savedTeam = parseClassroomTeam(record?.classroomTeam);
  if (record?.classroomTeamInitialized === "true" || savedTeam.length > 0) return savedTeam;
  return officialClassroomTeamForCourse(course);
};

type CaseIntervention = {
  id: string;
  date: string;
  action: string;
  by: string;
  outcome: string;
};

// Detects whether a calendar event title corresponds to an orientation class
// ("Acompañamiento orientación", "Clase de orientación", or any "orientación"
// mention paired with a course identifier), and returns a normalized display
// title plus the matched course.
const matchOrientationEvent = (summary: string): { isOrientation: boolean; course: string; displayTitle: string } => {
  const text = summary || "";
  const normalized = normalize(text);
  const isOrientation = /orientacion/.test(normalized);
  if (!isOrientation) return { isOrientation: false, course: "", displayTitle: text };
  // Try to match a known official course by name (longest first to win specificity).
  const officialByLength = [...officialCourses].sort((a, b) => b.name.length - a.name.length);
  let course = "";
  for (const c of officialByLength) {
    const normCourse = normalize(c.name);
    if (normCourse && normalized.includes(normCourse)) {
      course = c.name;
      break;
    }
  }
  // Fallback: a token after a +, -, or : that looks like a grade ("4°A", "II° Medio B").
  if (!course) {
    const m = text.match(/[+\-:|]\s*([A-Za-zÁÉÍÓÚáéíóúÑñ0-9°º\s]{1,30})$/);
    if (m) course = m[1].trim();
  }
  const displayTitle = course
    ? `Clase de orientación · ${course}`
    : text.replace(/acompañamiento\s+orientación/i, "Clase de orientación").trim();
  return { isOrientation: true, course, displayTitle };
};

const isPlaceholderOrientationText = (value: string | undefined) => {
  const normalized = normalize(value || "");
  return !normalized ||
    normalized === "clase por definir" ||
    normalized === "por definir" ||
    normalized === "sin tema definido" ||
    normalized === "sesion por definir";
};

const isGenericOrientationTopic = (value: string | undefined) => /^sesion\s+\d+$/i.test(normalize(value || ""));

// Un link (Canva, Drive, Docs…) nunca sirve como título legible de la clase.
const isLinkLikeText = (value: string | undefined) => /^(https?:\/\/|www\.)/i.test(String(value || "").trim());

// Agrupa clases por taller: un mismo taller se dicta en varios cursos y
// comparte materiales (Canva, planificación y carpeta). Los grupos con clases
// sin Canva van primero; luego por fecha.
type MaterialGroup = { key: string; title: string; records: DataRecord[] };
const orientationMaterialWeekKey = (dateValue: string | undefined) => {
  const clean = String(dateValue || "").slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(clean)) return "sin-fecha";
  const [year, month, day] = clean.split("-").map(Number);
  return toISODate(mondayOfWeek(new Date(year, month - 1, day)));
};

const FOURTH_GRADE_OVERRIDE = {
  weekStart: "2026-07-27",
  weekEnd: "2026-07-31",
  title: "Evaluación de Sexualidad y RICE (Reglamento Interno de Convivencia Escolar)",
  axis: "Intervención Formativa",
  reason: "Actividad extraordinaria de Sexualidad y RICE. La clase SENDA sugerida se posterga a la próxima semana.",
};

const orientationClassOverride = (course: string, date: string) =>
  columnaCourseKey(course).startsWith("4basico") && date >= FOURTH_GRADE_OVERRIDE.weekStart && date <= FOURTH_GRADE_OVERRIDE.weekEnd
    ? FOURTH_GRADE_OVERRIDE
    : null;

const buildMaterialGroups = (records: DataRecord[]): MaterialGroup[] => {
  const groups = new Map<string, { title: string; records: DataRecord[] }>();
  records.forEach((record) => {
    const rawTitle = (record.topic || "").trim();
    const title = rawTitle && !isPlaceholderOrientationText(rawTitle) && !isGenericOrientationTopic(rawTitle)
      ? rawTitle
      : "Tema por definir";
    const key = `${orientationMaterialWeekKey(record.date)}::${normalize(title) || record.id}`;
    const group = groups.get(key) || { title, records: [] };
    group.records.push(record);
    groups.set(key, group);
  });
  const missing = (items: DataRecord[]) => items.filter((record) => !(record.canvaLink || record.evidence || "").trim()).length;
  return Array.from(groups.entries())
    .map(([key, group]) => ({
      key,
      title: group.title,
      records: group.records.sort((a, b) => String(a.date || "").localeCompare(String(b.date || "")) || String(a.course || "").localeCompare(String(b.course || ""), "es")),
    }))
    .sort((a, b) => (missing(b.records) ? 1 : 0) - (missing(a.records) ? 1 : 0) || String(a.records[0]?.date || "").localeCompare(String(b.records[0]?.date || "")));
};

// Deja que el navegador pinte primero la respuesta visual del clic antes de
// recalcular la bitácora completa. Esto evita que interacciones sobre textos
// truncados queden atribuidas como tareas largas de INP.
const startAfterNextPaint = (update: () => void) => {
  if (typeof window === "undefined") {
    update();
    return;
  }
  window.requestAnimationFrame(() => {
    window.requestAnimationFrame(() => React.startTransition(update));
  });
};

const meaningfulOrientationNotes = (record: DataRecord) => {
  const notes = record.notes || "";
  return normalize(notes).includes("fecha ajustada por feriado") ? "" : notes;
};

// Los datos importados usan variantes en masculino ("Realizado", "Reprogramado");
// esta forma canónica es la que entienden los selectores y filtros de la bitácora.
const canonicalOrientationStatus = (status: string | undefined) => {
  const value = status || "";
  if (/realizad/i.test(value)) return "Realizada";
  if (/reprogramad/i.test(value)) return "Reprogramada";
  if (/planificad/i.test(value)) return "Planificada";
  if (/cancelad|suspendid/i.test(value)) return "Cancelada";
  return "Pendiente";
};

// Los registros importados guardan la planificación y la carpeta como nombre del
// documento o de la semana, no como URL: en ese caso el botón abre la búsqueda de Drive.
// Una clase puede tener más de un material (por ejemplo, el Consejo de Curso
// común más el RICE de 4° básico). Se admite un enlace por línea, con una
// etiqueta opcional antes de "|" o ":" para nombrar el botón.
type ResourceLink = { label: string; url: string };

const parseResourceLinks = (value: string | undefined, defaultLabel = "Canva"): ResourceLink[] => {
  const text = String(value || "").trim();
  if (!text) return [];
  return text
    .split(/\r?\n/)
    .flatMap((line) => line.split(/\s*[,;]\s*(?=https?:\/\/)/))
    .map((part) => part.trim())
    .filter(Boolean)
    .map((part) => {
      const urlMatch = part.match(/https?:\/\/\S+/);
      if (!urlMatch) return null;
      const url = urlMatch[0];
      const label = part.slice(0, part.indexOf(url)).replace(/[|:\-–—]\s*$/, "").trim();
      return { label: label || defaultLabel, url };
    })
    .filter((item): item is ResourceLink => Boolean(item));
};

const orientationDocUrl = (value: string | undefined) => {
  const text = String(value || "").trim();
  if (!text) return "";
  if (/^https?:\/\//i.test(text)) return text;
  return `https://drive.google.com/drive/search?q=${encodeURIComponent(text)}`;
};

// La planificación y la carpeta suelen guardarse como nombre del documento en vez
// de URL, así que aquí una entrada puede tener sólo etiqueta, sólo enlace o ambos.
type MaterialEntry = { label: string; url: string };

const parseMaterialEntries = (value: string | undefined): MaterialEntry[] =>
  String(value || "")
    .split(/\r?\n/)
    .flatMap((line) => line.split(/\s*[,;]\s*(?=https?:\/\/)/))
    .map((part) => part.trim())
    .filter(Boolean)
    .map((part) => {
      const urlMatch = part.match(/https?:\/\/\S+/);
      if (!urlMatch) return { label: part, url: "" };
      const url = urlMatch[0];
      return { label: part.slice(0, part.indexOf(url)).replace(/[|:\-–—]\s*$/, "").trim(), url };
    });

const serializeMaterialEntries = (entries: MaterialEntry[]) =>
  entries
    .map(({ label, url }) => {
      const cleanLabel = label.trim();
      const cleanUrl = url.trim();
      if (cleanLabel && cleanUrl) return `${cleanLabel} | ${cleanUrl}`;
      return cleanUrl || cleanLabel;
    })
    .filter(Boolean)
    .join("\n");

// Cada entrada se muestra como su propio botón: una clase puede tener más de un
// Canva, más de una planificación o más de una carpeta.
const materialButtons = (value: string | undefined, defaultLabel: string) =>
  parseMaterialEntries(value)
    .map((entry) => ({ label: entry.label || defaultLabel, url: orientationDocUrl(entry.url || entry.label) }))
    .filter((entry) => Boolean(entry.url));

// Editor de materiales de una clase: permite sumar tantos Canva, planificaciones
// o carpetas como tenga la clase (4° básico, por ejemplo, tiene dos Canva).
function MaterialListEditor({
  label,
  value,
  onChange,
  disabled,
  placeholderLabel,
  placeholderValue,
  addLabel,
  accent,
  allowNameOnly = false,
  hint,
}: {
  label: string;
  value: string;
  onChange: (value: string) => void;
  disabled?: boolean;
  placeholderLabel: string;
  placeholderValue: string;
  addLabel: string;
  accent: "cyan" | "indigo" | "emerald";
  allowNameOnly?: boolean;
  hint?: string;
}) {
  // Las filas viven en estado local porque una fila recién añadida está vacía y
  // no sobrevive a la serialización: derivarlas del valor haría que "Añadir" no
  // mostrara nada. Se resincronizan sólo cuando el valor cambia desde fuera.
  const [rows, setRows] = useState<MaterialEntry[]>(() => {
    const parsed = parseMaterialEntries(value);
    return parsed.length ? parsed : [{ label: "", url: "" }];
  });
  const lastSerializedRef = React.useRef(value);
  useEffect(() => {
    if (value === lastSerializedRef.current) return;
    lastSerializedRef.current = value;
    const parsed = parseMaterialEntries(value);
    setRows(parsed.length ? parsed : [{ label: "", url: "" }]);
  }, [value]);

  const commit = (next: MaterialEntry[]) => {
    setRows(next.length ? next : [{ label: "", url: "" }]);
    const serialized = serializeMaterialEntries(next);
    lastSerializedRef.current = serialized;
    onChange(serialized);
  };
  const updateRow = (index: number, changes: Partial<MaterialEntry>) =>
    commit(rows.map((row, i) => (i === index ? { ...row, ...changes } : row)));

  const accentClasses = {
    cyan: "border-cyan-200 bg-cyan-50 text-cyan-700 hover:bg-cyan-100",
    indigo: "border-indigo-200 bg-indigo-50 text-indigo-700 hover:bg-indigo-100",
    emerald: "border-emerald-200 bg-emerald-50 text-emerald-700 hover:bg-emerald-100",
  }[accent];

  return (
    <div className="block">
      <span className="text-[11px] font-bold uppercase tracking-wide text-slate-500">{label}</span>
      <div className="mt-1 space-y-2">
        {rows.map((row, index) => {
          const openUrl = orientationDocUrl(row.url || (allowNameOnly ? row.label : ""));
          return (
            <div key={index} className="flex flex-wrap items-center gap-2 sm:flex-nowrap">
              <input
                disabled={disabled}
                value={row.label}
                onChange={(event) => updateRow(index, { label: event.target.value })}
                placeholder={placeholderLabel}
                className="min-w-0 flex-1 rounded-md border border-slate-200 px-2.5 py-2 text-sm outline-none focus:border-blue-500 disabled:bg-slate-100 sm:max-w-[42%]"
              />
              <input
                disabled={disabled}
                value={row.url}
                onChange={(event) => updateRow(index, { url: event.target.value })}
                placeholder={placeholderValue}
                className="min-w-0 flex-1 rounded-md border border-slate-200 px-2.5 py-2 text-sm outline-none focus:border-blue-500 disabled:bg-slate-100"
              />
              {openUrl ? (
                <a href={openUrl} target="_blank" rel="noopener noreferrer" title={openUrl} className="inline-flex shrink-0 items-center justify-center rounded-md border border-blue-200 bg-blue-50 px-2.5 py-2 text-xs font-bold text-blue-700 hover:bg-blue-100">
                  <ExternalLink className="h-3.5 w-3.5" />
                </a>
              ) : null}
              {rows.length > 1 ? (
                <button
                  type="button"
                  disabled={disabled}
                  onClick={() => commit(rows.filter((_, i) => i !== index))}
                  title="Quitar este material"
                  className="inline-flex shrink-0 items-center justify-center rounded-md border border-rose-200 bg-white px-2.5 py-2 text-rose-600 hover:bg-rose-50 disabled:opacity-50"
                >
                  <Trash2 className="h-3.5 w-3.5" />
                </button>
              ) : null}
            </div>
          );
        })}
      </div>
      <button
        type="button"
        disabled={disabled}
        onClick={() => commit([...rows, { label: "", url: "" }])}
        className={`mt-2 inline-flex items-center gap-1.5 rounded-lg border px-2.5 py-1.5 text-[11px] font-bold transition disabled:opacity-50 ${accentClasses}`}
      >
        <Plus className="h-3.5 w-3.5" /> {addLabel}
      </button>
      {hint ? <span className="mt-1.5 block text-[10px] font-semibold leading-4 text-slate-400">{hint}</span> : null}
    </div>
  );
}

// ---- Feedback de clase (pauta de acompañamiento Colegio San Lucas) ----

const FEEDBACK_SECTION_CULTURE = [
  "Describe la conducta esperada previo a comenzar la clase o ante cualquier actividad de esta.",
  "Nombra la fortaleza del carácter cuando anticipa, felicita o corrige.",
  "Al nombrar la fortaleza la relaciona con la conducta esperada o no esperada (ejemplifica).",
  "Felicita conductas positivas, explicitando la conducta reconocida y vinculándola con una fortaleza.",
  "Corrige formativamente: explicita lo que se espera y menciona la fortaleza vinculada con dicha conducta.",
  "Mantiene un ambiente ordenado y coherente con las fortalezas y reglamentos.",
  "Explica el sentido de normas y procedimientos (el porqué de una norma, corrección o felicitación).",
];

const FEEDBACK_SECTION_STRENGTHS = [
  "Contextualiza la clase nombrando la fortaleza que se trabajará ese día u hora.",
  "Recuerda el significado de la fortaleza del carácter.",
  "Conecta la clase con conductas asociadas a la fortaleza.",
  "Invita a reflexionar sobre el desarrollo personal.",
  "Invita a identificar aprendizajes vinculados a la fortaleza.",
  "Utiliza libros de formación y/o material de orientación con los estudiantes.",
];

const FEEDBACK_COMPREHENSION_STRATEGIES = ["Localización", "Inferencia", "Reflexión"];

type ClassFeedbackData = {
  teacher: string;
  teacherEmail: string;
  subject: string;
  startTime: string;
  endTime: string;
  observer: string;
  observationNumber: string;
  cultureItems: string[];
  strengthItems: string[];
  comprehensionUsed: string;
  comprehensionStrategies: string[];
  comprehensionEvidence: string;
  thinkingUsed: string;
  // Nombres exactos del Kit de estrategias Focus; el detalle queda para lo que
  // no está en el cuadernillo o para precisar cómo se aplicó.
  thinkingStrategies: string[];
  thinkingDetail: string;
  climateUsed: string;
  climateStrategies: string[];
  climateDetail: string;
  generalEvidence: string;
  improvements: string;
  updatedAt?: string;
};

const emptyClassFeedback = (): ClassFeedbackData => ({
  teacher: "",
  teacherEmail: "",
  subject: "Orientación",
  startTime: "",
  endTime: "",
  observer: "",
  observationNumber: "",
  cultureItems: FEEDBACK_SECTION_CULTURE.map(() => ""),
  strengthItems: FEEDBACK_SECTION_STRENGTHS.map(() => ""),
  comprehensionUsed: "",
  comprehensionStrategies: [],
  comprehensionEvidence: "",
  thinkingUsed: "",
  thinkingStrategies: [],
  thinkingDetail: "",
  climateUsed: "",
  climateStrategies: [],
  climateDetail: "",
  generalEvidence: "",
  improvements: "",
});

const parseClassFeedback = (raw: string | undefined): ClassFeedbackData => {
  const base = emptyClassFeedback();
  if (!raw) return base;
  try {
    const parsed = JSON.parse(raw) as Partial<ClassFeedbackData>;
    return {
      ...base,
      ...parsed,
      cultureItems: FEEDBACK_SECTION_CULTURE.map((_, index) => parsed.cultureItems?.[index] || ""),
      strengthItems: FEEDBACK_SECTION_STRENGTHS.map((_, index) => parsed.strengthItems?.[index] || ""),
      comprehensionStrategies: Array.isArray(parsed.comprehensionStrategies) ? parsed.comprehensionStrategies : [],
      thinkingStrategies: Array.isArray(parsed.thinkingStrategies) ? parsed.thinkingStrategies : [],
      climateStrategies: Array.isArray(parsed.climateStrategies) ? parsed.climateStrategies : [],
    };
  } catch {
    return base;
  }
};

const classFeedbackSummaryText = (record: DataRecord, data: ClassFeedbackData) => {
  const mark = (value: string) => (value === "si" ? "Sí" : value === "no" ? "No" : "—");
  const lines: string[] = [
    `FEEDBACK DE CLASE · ${record.course || "Sin curso"} · ${record.date || "Sin fecha"}`,
    `Docente: ${data.teacher || "—"} · Asignatura: ${data.subject || "—"} · Horario: ${data.startTime || "—"} a ${data.endTime || "—"}`,
    `Observador/a: ${data.observer || "—"} · N° de acompañamiento: ${data.observationNumber || "—"}`,
    `Clase: ${record.topic || "—"} · Fortaleza/acción: ${record.axis || record.characterStrength || "—"}`,
    "",
    "1. INTERVENCIÓN FORMATIVA Y CULTURA INSTITUCIONAL",
    ...FEEDBACK_SECTION_CULTURE.map((item, index) => `  [${mark(data.cultureItems[index])}] ${item}`),
    "",
    "2. TRABAJO DE FORTALEZAS DEL CARÁCTER EN LA CLASE",
    ...FEEDBACK_SECTION_STRENGTHS.map((item, index) => `  [${mark(data.strengthItems[index])}] ${item}`),
    "",
    "3. ESTRATEGIAS PEDAGÓGICAS OBSERVADAS",
    `  a. Habilidad de comprensión: ${mark(data.comprehensionUsed)}${data.comprehensionStrategies.length ? ` (${data.comprehensionStrategies.join(", ")})` : ""}`,
  ];
  if (data.comprehensionEvidence.trim()) lines.push(`     Evidencia: ${data.comprehensionEvidence.trim()}`);
  const strategyTail = (names: string[], detail: string) =>
    `${names.length ? ` (${names.join(", ")})` : ""}${detail.trim() ? ` · ${detail.trim()}` : ""}`;
  lines.push(`  b. Estrategias de pensamiento: ${mark(data.thinkingUsed)}${strategyTail(data.thinkingStrategies, data.thinkingDetail)}`);
  lines.push(`  c. Estrategias de clima de aula: ${mark(data.climateUsed)}${strategyTail(data.climateStrategies, data.climateDetail)}`);
  if (data.generalEvidence.trim()) {
    lines.push("", "4. EVIDENCIA / OBSERVACIONES GENERALES", `  ${data.generalEvidence.trim()}`);
  }
  if (data.improvements.trim()) {
    lines.push("", "5. ELEMENTOS DESTACADOS Y SUGERENCIAS PARA LA MEJORA", `  ${data.improvements.trim()}`);
  }
  lines.push("", "Favor responder acusando recibo.");
  return lines.join("\n");
};

// ---- Correo HTML del feedback (con colores) para pegar en Gmail ----
const escapeFeedbackHtml = (value: string) =>
  String(value || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/\n/g, "<br>");

const feedbackMarkBadge = (value: string) => {
  if (value === "si") return `<span style="display:inline-block;padding:4px 10px;border-radius:999px;background-color:#e8f5ee;color:#176b45;font-size:11px;font-weight:800;letter-spacing:.04em;">&#10003;&nbsp; SÍ</span>`;
  if (value === "no") return `<span style="display:inline-block;padding:4px 10px;border-radius:999px;background-color:#fff0ed;color:#a63d2f;font-size:11px;font-weight:800;letter-spacing:.04em;">&#10005;&nbsp; NO</span>`;
  return `<span style="display:inline-block;padding:4px 10px;border-radius:999px;background-color:#f1f3f5;color:#7a8491;font-size:11px;font-weight:800;">&mdash;</span>`;
};

const feedbackChecklistHtml = (items: string[], values: string[]) =>
  items
    .map(
      (item, index) => `<tr>
        <td style="padding:12px 16px;border-bottom:1px solid #ece9e2;font-size:13px;line-height:1.55;color:#34404c;">${escapeFeedbackHtml(item)}</td>
        <td style="padding:12px 16px;border-bottom:1px solid #ece9e2;text-align:right;white-space:nowrap;">${feedbackMarkBadge(values[index] || "")}</td>
      </tr>`,
    )
    .join("");

const feedbackSectionCard = (number: string, eyebrow: string, title: string, accent: string, inner: string) => `
  <table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="width:100%;margin-top:22px;border-collapse:separate;border-spacing:0;border:1px solid #e4e1da;border-radius:14px;background-color:#ffffff;">
    <tr>
      <td style="width:54px;padding:17px 0 15px 16px;vertical-align:top;">
        <span style="display:inline-block;width:34px;height:34px;border-radius:50%;background-color:${accent};color:#ffffff;font-family:Arial,sans-serif;font-size:14px;font-weight:800;line-height:34px;text-align:center;">${escapeFeedbackHtml(number)}</span>
      </td>
      <td style="padding:15px 16px 13px 8px;vertical-align:top;">
        <div style="font-family:Arial,sans-serif;font-size:9px;font-weight:800;letter-spacing:.14em;text-transform:uppercase;color:${accent};">${escapeFeedbackHtml(eyebrow)}</div>
        <div style="margin-top:3px;font-family:Georgia,'Times New Roman',serif;font-size:19px;line-height:1.25;color:#152d47;">${escapeFeedbackHtml(title)}</div>
      </td>
    </tr>
    <tr><td colspan="2" style="padding:0;">${inner}</td></tr>
  </table>`;

// En Android/iOS la URL de Gmail web abre una pestaña del navegador dentro de la
// app; `mailto:` en cambio entrega el correo al cliente nativo (Gmail), que es
// donde se puede pegar el diseño copiado. En escritorio se mantiene Gmail web.
const isMobileDevice = () =>
  typeof navigator !== "undefined" && /Android|iPhone|iPad|iPod/i.test(navigator.userAgent);

// Copia el correo con formato. La API moderna falla en varios navegadores
// móviles, así que hay un respaldo con execCommand sobre un nodo editable
// oculto, que es lo que sí reconoce Gmail de Android al pegar.
const copyRichEmailSync = (html: string) => {
  try {
    const holder = document.createElement("div");
    holder.setAttribute("contenteditable", "true");
    holder.innerHTML = html;
    // Fuera de pantalla pero seleccionable: display:none impediría copiar.
    holder.style.cssText = "position:fixed;left:-9999px;top:0;opacity:0;white-space:pre-wrap;";
    document.body.appendChild(holder);
    const range = document.createRange();
    range.selectNodeContents(holder);
    const selection = window.getSelection();
    selection?.removeAllRanges();
    selection?.addRange(range);
    const copied = document.execCommand("copy");
    selection?.removeAllRanges();
    document.body.removeChild(holder);
    return copied;
  } catch {
    return false;
  }
};

// Se ejecutan los dos métodos, no uno u otro: en Android execCommand dice haber
// copiado pero deja solo texto plano, así que después se sobrescribe el
// portapapeles con la API moderna, que sí declara el tipo text/html que Gmail
// necesita para pegar con formato. El orden importa porque execCommand exige el
// gesto del usuario todavía vigente y cualquier await previo lo consume.
const copyRichEmail = async (html: string, plain: string) => {
  const legacyCopied = copyRichEmailSync(html);
  try {
    const ClipboardItemCtor = (window as unknown as { ClipboardItem?: typeof ClipboardItem }).ClipboardItem;
    if (navigator.clipboard && ClipboardItemCtor) {
      await navigator.clipboard.write([
        new ClipboardItemCtor({
          "text/html": new Blob([html], { type: "text/html" }),
          "text/plain": new Blob([plain], { type: "text/plain" }),
        }),
      ]);
      return true;
    }
  } catch {
    // Queda lo copiado por execCommand.
  }
  return legacyCopied;
};

const openMailCompose = ({ to, subject, body }: { to: string; subject: string; body?: string }) => {
  if (isMobileDevice()) {
    const query = [`subject=${encodeURIComponent(subject)}`, body ? `body=${encodeURIComponent(body)}` : ""]
      .filter(Boolean)
      .join("&");
    // La dirección va sin codificar (RFC 6068); location.href en vez de
    // window.open porque los esquemas mailto se bloquean en pestañas nuevas.
    window.location.href = `mailto:${to.replace(/\s+/g, "")}?${query}`;
    return;
  }
  const params = `view=cm&fs=1&tf=1&to=${encodeURIComponent(to)}&su=${encodeURIComponent(subject)}${body ? `&body=${encodeURIComponent(body)}` : ""}`;
  window.open(`https://mail.google.com/mail/?${params}`, "_blank", "noopener");
};

