// Los colores de cada sección de la pauta son los mismos del correo editorial
// que recibe la docente, para que pantalla y correo se lean como una sola pieza.
const FEEDBACK_SECTION_ACCENTS = {
  teal: { badge: "bg-teal-700", eyebrow: "text-teal-700", ring: "ring-teal-100", soft: "from-teal-50" },
  violet: { badge: "bg-violet-700", eyebrow: "text-violet-700", ring: "ring-violet-100", soft: "from-violet-50" },
  amber: { badge: "bg-amber-600", eyebrow: "text-amber-700", ring: "ring-amber-100", soft: "from-amber-50" },
  slate: { badge: "bg-slate-700", eyebrow: "text-slate-600", ring: "ring-slate-100", soft: "from-slate-50" },
} as const;

function FeedbackSectionCard({ number, eyebrow, title, accent, children }: {
  number: string;
  eyebrow: string;
  title: string;
  accent: keyof typeof FEEDBACK_SECTION_ACCENTS;
  children: React.ReactNode;
}) {
  const tone = FEEDBACK_SECTION_ACCENTS[accent];
  return (
    <section className={`overflow-hidden rounded-2xl bg-white shadow-sm ring-1 ${tone.ring}`}>
      <header className={`flex items-center gap-3 bg-gradient-to-r ${tone.soft} to-white px-4 py-3`}>
        <span className={`grid h-8 w-8 shrink-0 place-items-center rounded-full text-xs font-black text-white ${tone.badge}`}>{number}</span>
        <div className="min-w-0">
          <p className={`text-[9px] font-black uppercase tracking-[0.14em] ${tone.eyebrow}`}>{eyebrow}</p>
          <h3 className="truncate text-sm font-bold text-slate-900">{title}</h3>
        </div>
      </header>
      <div className="px-4 py-3">{children}</div>
    </section>
  );
}

// Selector múltiple de estrategias del Kit Focus: se busca por nombre o por el
// propósito de la estrategia, y las seleccionadas quedan visibles como chips.
function StrategyMultiSelect({
  catalog,
  selected,
  onChange,
  accent,
  emptyLabel,
}: {
  catalog: FocusStrategy[];
  selected: string[];
  onChange: (next: string[]) => void;
  accent: "violet" | "rose";
  emptyLabel: string;
}) {
  const [open, setOpen] = useState(false);
  const [search, setSearch] = useState("");
  const query = normalize(search);
  const visible = query
    ? catalog.filter((item) => normalize(`${item.n} ${item.name} ${item.purpose}`).includes(query))
    : catalog;
  const toggle = (name: string) =>
    onChange(selected.includes(name) ? selected.filter((item) => item !== name) : [...selected, name]);

  const chip = accent === "violet"
    ? "bg-violet-100 text-violet-800 ring-violet-300"
    : "bg-rose-100 text-rose-800 ring-rose-300";

  return (
    <div className="mt-2">
      <div className="flex flex-wrap items-center gap-1.5">
        {selected.length ? (
          selected.map((name) => (
            <button
              key={name}
              type="button"
              onClick={() => toggle(name)}
              title="Quitar esta estrategia"
              className={`inline-flex items-center gap-1 rounded-lg px-2 py-1 text-[11px] font-bold ring-1 transition hover:opacity-80 ${chip}`}
            >
              {name} <X className="h-3 w-3" />
            </button>
          ))
        ) : (
          <span className="text-[11px] font-semibold text-slate-400">{emptyLabel}</span>
        )}
      </div>
      <button
        type="button"
        onClick={() => setOpen((current) => !current)}
        className="mt-2 inline-flex items-center gap-1.5 rounded-lg border border-slate-200 bg-white px-2.5 py-1.5 text-[11px] font-bold text-slate-700 transition hover:bg-slate-50"
      >
        <Search className="h-3.5 w-3.5" />
        {open ? "Cerrar catálogo" : `Elegir del cuadernillo (${catalog.length})`}
        <ChevronDown className={`h-3.5 w-3.5 transition ${open ? "rotate-180" : ""}`} />
      </button>
      {open ? (
        <div className="mt-2 rounded-xl border border-slate-200 bg-white shadow-sm">
          <div className="border-b border-slate-100 p-2">
            <input
              autoFocus
              value={search}
              onChange={(event) => setSearch(event.target.value)}
              placeholder="Buscar por nombre o propósito…"
              className="w-full rounded-lg border border-slate-200 px-2.5 py-2 text-sm outline-none focus:border-blue-500"
            />
          </div>
          <div className="max-h-64 overflow-y-auto">
            {visible.length ? (
              visible.map((item) => {
                const active = selected.includes(item.name);
                return (
                  <button
                    key={item.n}
                    type="button"
                    onClick={() => toggle(item.name)}
                    className={`flex w-full items-start gap-2.5 border-b border-slate-50 px-3 py-2.5 text-left transition last:border-b-0 ${active ? "bg-slate-50" : "hover:bg-slate-50/60"}`}
                  >
                    <span className={`mt-0.5 grid h-5 w-5 shrink-0 place-items-center rounded-md text-[10px] font-black ${active ? (accent === "violet" ? "bg-violet-600 text-white" : "bg-rose-600 text-white") : "bg-slate-100 text-slate-500"}`}>
                      {active ? <Check className="h-3 w-3" /> : item.n}
                    </span>
                    <span className="min-w-0">
                      <span className="block text-[13px] font-bold leading-5 text-slate-800">{item.name}</span>
                      <span className="mt-0.5 block text-[11px] leading-4 text-slate-500">{item.purpose}</span>
                    </span>
                  </button>
                );
              })
            ) : (
              <p className="px-3 py-6 text-center text-xs font-semibold text-slate-400">Ninguna estrategia coincide con esa búsqueda.</p>
            )}
          </div>
        </div>
      ) : null}
    </div>
  );
}

function FeedbackYesNo({ value, onChange }: { value: string; onChange: (value: string) => void }) {
  return (
    <div className="flex w-full shrink-0 gap-1.5 sm:w-auto">
      {(["si", "no"] as const).map((option) => (
        <button
          key={option}
          type="button"
          onClick={() => onChange(value === option ? "" : option)}
          className={`min-h-9 flex-1 rounded-lg px-3 py-1.5 text-xs font-bold ring-1 transition sm:min-h-0 sm:flex-none sm:text-[11px] ${
            value === option
              ? option === "si"
                ? "bg-emerald-100 text-emerald-700 ring-emerald-300"
                : "bg-rose-100 text-rose-700 ring-rose-300"
              : "bg-white text-slate-400 ring-slate-200 hover:bg-slate-50"
          }`}
        >
          {option === "si" ? "Sí" : "No"}
        </button>
      ))}
    </div>
  );
}

function OrientationFeedbackModal({
  record,
  ownerName,
  accessToken,
  autoObservationNumber,
  defaultStartTime,
  defaultEndTime,
  onClose,
  onSave,
  onAutoSave,
  onDelete,
}: {
  record: DataRecord;
  ownerName: string;
  accessToken: string;
  autoObservationNumber: string;
  defaultStartTime: string;
  defaultEndTime: string;
  onClose: () => void;
  onSave: (data: ClassFeedbackData) => void;
  onAutoSave: (data: ClassFeedbackData) => void;
  onDelete: () => void;
}) {
  const [data, setData] = useState<ClassFeedbackData>(() => {
    const parsed = parseClassFeedback(record.classFeedback);
    const courseTeacher = headTeacherForCourse(record.course || "");
    const allowedTeacher = FEEDBACK_TEACHER_OPTIONS.find((teacher) =>
      (!teacher.isTest && parsed.teacherEmail && teacher.email === parsed.teacherEmail.trim().toLowerCase()) ||
      (!teacher.isTest && parsed.teacher && normalize(teacher.name) === normalize(parsed.teacher))
    );
    const fallbackTeacher = courseTeacher
      ? FEEDBACK_TEACHER_OPTIONS.find((teacher) => !teacher.isTest && teacher.email === courseTeacher.email)
      : null;
    const selectedTeacher = allowedTeacher || fallbackTeacher;
    parsed.teacher = selectedTeacher?.name || "";
    parsed.teacherEmail = selectedTeacher?.email || "";
    if (!parsed.observer) parsed.observer = ownerName;
    // El número corresponde a la posición real de la clase realizada en el curso,
    // independientemente de cuántas clases anteriores tengan feedback guardado.
    parsed.observationNumber = autoObservationNumber;
    // El horario oficial es el punto de partida y se puede corregir manualmente.
    if (!parsed.startTime) parsed.startTime = defaultStartTime;
    if (!parsed.endTime) parsed.endTime = defaultEndTime;
    return parsed;
  });
  const [copied, setCopied] = useState(false);
  const [testTeacherActive, setTestTeacherActive] = useState(false);
  const emailFeedbackData = testTeacherActive
    ? { ...data, teacher: FEEDBACK_TEST_TEACHER.name, teacherEmail: FEEDBACK_TEST_TEACHER.email }
    : data;
  const lastAutoSavedRef = React.useRef(JSON.stringify(data));
  const update = (changes: Partial<ClassFeedbackData>) => setData((current) => ({ ...current, ...changes }));
  const updateItem = (key: "cultureItems" | "strengthItems", index: number, value: string) =>
    setData((current) => ({ ...current, [key]: current[key].map((item, i) => (i === index ? value : item)) }));

  useEffect(() => {
    const serialized = JSON.stringify(data);
    if (serialized === lastAutoSavedRef.current) return;
    const timer = window.setTimeout(() => {
      lastAutoSavedRef.current = serialized;
      onAutoSave(data);
    }, 900);
    return () => window.clearTimeout(timer);
  }, [data, onAutoSave]);

  const saveAndClose = () => {
    const serialized = JSON.stringify(data);
    if (serialized !== lastAutoSavedRef.current) {
      lastAutoSavedRef.current = serialized;
      onAutoSave(data);
    }
    onClose();
  };

  const saveFeedback = () => {
    lastAutoSavedRef.current = JSON.stringify(data);
    onSave(data);
  };

  const deleteFeedback = () => {
    if (!window.confirm(`¿Eliminar definitivamente el feedback de ${record.course || "esta clase"}${record.date ? ` del ${record.date}` : ""}? La clase y sus materiales se conservarán.`)) return;
    lastAutoSavedRef.current = JSON.stringify(data);
    onDelete();
  };

  const copySummary = async () => {
    try {
      await navigator.clipboard.writeText(classFeedbackSummaryText(record, emailFeedbackData));
      setCopied(true);
      window.setTimeout(() => setCopied(false), 2500);
    } catch {
      window.prompt("Copia el resumen manualmente:", classFeedbackSummaryText(record, emailFeedbackData));
    }
  };

  const teacherEmail = emailFeedbackData.teacherEmail || "";
  const feedbackComplete = [...data.cultureItems, ...data.strengthItems, data.comprehensionUsed, data.thinkingUsed, data.climateUsed]
    .every((value) => value === "si" || value === "no");
  const [emailState, setEmailState] = useState<"idle" | "error">("idle");
  const [emailHint, setEmailHint] = useState("");
  // Vista previa del correo renderizada: respaldo cuando el portapapeles del
  // celular no conserva el formato (se copia a mano desde aquí).
  const [previewHtml, setPreviewHtml] = useState("");

  // El portapapeles de Android no conserva el formato al pegar en Gmail, así que
  // la vía fiel al diseño es un PDF: se imprime el correo desde un iframe y el
  // sistema ofrece "Guardar como PDF" para adjuntarlo al correo.
  const printFeedbackPdf = () => {
    if (!feedbackComplete) {
      setEmailState("error");
      setEmailHint("Completa todos los indicadores Sí/No antes de generar el PDF.");
      return;
    }
    lastAutoSavedRef.current = JSON.stringify(data);
    onAutoSave(data);
    const title = `Feedback ${record.course || ""} ${record.date || ""}`.replace(/\s+/g, " ").trim();
    const frame = document.createElement("iframe");
    frame.setAttribute("aria-hidden", "true");
    frame.style.cssText = "position:fixed;right:0;bottom:0;width:0;height:0;border:0;";
    document.body.appendChild(frame);
    const doc = frame.contentWindow?.document;
    if (!doc) { frame.remove(); return; }
    doc.open();
    doc.write(`<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${title}</title><style>@page{margin:12mm}body{margin:0;-webkit-print-color-adjust:exact;print-color-adjust:exact}</style></head><body>${classFeedbackEmailHtml(record, emailFeedbackData)}</body></html>`);
    doc.close();
    const run = () => {
      frame.contentWindow?.focus();
      frame.contentWindow?.print();
      window.setTimeout(() => frame.remove(), 2000);
    };
    if (doc.readyState === "complete") run();
    else frame.onload = run;
    setEmailState("idle");
    setEmailHint("Elige “Guardar como PDF” y luego adjúntalo en Gmail: el diseño se mantiene igual en cualquier teléfono.");
    window.setTimeout(() => setEmailHint(""), 12000);
  };

  const openFeedbackInGmail = async () => {
    if (!feedbackComplete) {
      setEmailState("error");
      setEmailHint("Completa todos los indicadores Sí/No antes de preparar el correo.");
      return;
    }
    if (!teacherEmail) {
      setEmailState("error");
      setEmailHint("Este curso no tiene correo de profesora jefe configurado.");
      return;
    }
    // Guarda el feedback antes de enviarlo para no perder cambios recientes.
    lastAutoSavedRef.current = JSON.stringify(data);
    onAutoSave(data);
    const subject = `Feedback de clase de Orientación · ${record.course || "Sin curso"}${record.date ? ` · ${record.date}` : ""}`;
    const html = classFeedbackEmailHtml(record, emailFeedbackData);
    const plain = classFeedbackSummaryText(record, emailFeedbackData);
    const richCopied = await copyRichEmail(html, plain);
    // Con formato copiado: Gmail se abre vacío y la profesora pega el correo con colores.
    // Sin permiso de portapapeles: se abre con el texto plano como respaldo.
    // En móvil se espera un instante: cambiar de app corta el copiado en curso.
    if (richCopied && isMobileDevice()) await new Promise((resolve) => window.setTimeout(resolve, 400));
    openMailCompose({ to: teacherEmail, subject, body: richCopied ? undefined : plain });
    setEmailState("idle");
    setEmailHint(richCopied
      ? (isMobileDevice()
        ? "Diseño copiado. En Gmail mantén presionado el cuerpo del correo y elige Pegar; revisa y envía."
        : "Diseño editorial copiado. En Gmail presiona ⌘V (o Ctrl+V), revisa el mensaje y envíalo.")
      : "Se abrió Gmail con una versión en texto porque el navegador no permitió copiar el diseño.");
    window.setTimeout(() => setEmailHint(""), 12000);
  };

  // ---- Relato hablado: se graba la voz y Tiza-IA completa la pauta ----
  const [voiceState, setVoiceState] = useState<"idle" | "recording" | "processing">("idle");
  const [voiceHint, setVoiceHint] = useState("");
  const [voiceError, setVoiceError] = useState("");
  const [voiceSeconds, setVoiceSeconds] = useState(0);
  const recorderRef = React.useRef<MediaRecorder | null>(null);
  const chunksRef = React.useRef<BlobPart[]>([]);

  useEffect(() => {
    if (voiceState !== "recording") return;
    const timer = window.setInterval(() => setVoiceSeconds((current) => current + 1), 1000);
    return () => window.clearInterval(timer);
  }, [voiceState]);

  // Al desmontar hay que soltar el micrófono: si no, el navegador lo deja tomado.
  useEffect(() => () => {
    recorderRef.current?.stream.getTracks().forEach((track) => track.stop());
  }, []);

  const applyAiFeedback = (incoming: Partial<ClassFeedbackData>) => {
    setData((current) => {
      // La IA sólo rellena lo que quedó vacío: nunca pisa lo que ya marcaste.
      const merge = (mine: string[], theirs: string[] | undefined) =>
        mine.map((value, index) => value || theirs?.[index] || "");
      const keepText = (mine: string, theirs: string | undefined) => mine.trim() || (theirs || "").trim();
      const mergeNames = (mine: string[], theirs: string[] | undefined) =>
        Array.from(new Set([...mine, ...(theirs || [])]));
      return {
        ...current,
        cultureItems: merge(current.cultureItems, incoming.cultureItems),
        strengthItems: merge(current.strengthItems, incoming.strengthItems),
        comprehensionUsed: current.comprehensionUsed || incoming.comprehensionUsed || "",
        comprehensionStrategies: mergeNames(current.comprehensionStrategies, incoming.comprehensionStrategies),
        comprehensionEvidence: keepText(current.comprehensionEvidence, incoming.comprehensionEvidence),
        thinkingUsed: current.thinkingUsed || incoming.thinkingUsed || "",
        thinkingStrategies: mergeNames(current.thinkingStrategies, incoming.thinkingStrategies),
        thinkingDetail: keepText(current.thinkingDetail, incoming.thinkingDetail),
        climateUsed: current.climateUsed || incoming.climateUsed || "",
        climateStrategies: mergeNames(current.climateStrategies, incoming.climateStrategies),
        climateDetail: keepText(current.climateDetail, incoming.climateDetail),
        generalEvidence: keepText(current.generalEvidence, incoming.generalEvidence),
        improvements: keepText(current.improvements, incoming.improvements),
      };
    });
  };

  const sendToTizaIa = async (payload: { audio?: Blob; text?: string }) => {
    setVoiceState("processing");
    setVoiceError("");
    setVoiceHint("Tiza-IA está escuchando el relato y completando la pauta…");
    try {
      const form = new FormData();
      if (payload.audio) form.append("audio", payload.audio, "relato.webm");
      if (payload.text) form.append("text", payload.text);
      form.append("context", JSON.stringify({
        course: record.course || "",
        date: record.date || "",
        topic: record.topic || "",
        strength: record.axis || record.characterStrength || "",
        teacher: data.teacher || "",
        cultureItems: FEEDBACK_SECTION_CULTURE,
        strengthItems: FEEDBACK_SECTION_STRENGTHS,
      }));
      const res = await fetch("/api/ai/feedback", {
        method: "POST",
        headers: { authorization: `Bearer ${accessToken}` },
        body: form,
      });
      const json = await res.json();
      if (!res.ok || !json?.feedback) throw new Error(json?.error || "Tiza-IA no pudo procesar el relato.");
      applyAiFeedback(json.feedback as Partial<ClassFeedbackData>);
      const filled = [...(json.feedback.cultureItems || []), ...(json.feedback.strengthItems || [])].filter(Boolean).length;
      setVoiceHint(`Listo: Tiza-IA completó ${filled} indicadores y redactó la evidencia. Revisa y ajusta lo que falte antes de enviar.`);
      window.setTimeout(() => setVoiceHint(""), 15000);
    } catch (error) {
      setVoiceError(error instanceof Error ? error.message : "No se pudo procesar el relato.");
      setVoiceHint("");
    } finally {
      setVoiceState("idle");
    }
  };

  const startRecording = async () => {
    setVoiceError("");
    if (typeof MediaRecorder === "undefined" || !navigator.mediaDevices?.getUserMedia) {
      setVoiceError("Este navegador no permite grabar audio. Escribe el relato en “Evidencia general” y usa el botón de redacción.");
      return;
    }
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const recorder = new MediaRecorder(stream);
      chunksRef.current = [];
      recorder.ondataavailable = (event) => { if (event.data.size) chunksRef.current.push(event.data); };
      recorder.onstop = () => {
        stream.getTracks().forEach((track) => track.stop());
        const blob = new Blob(chunksRef.current, { type: recorder.mimeType || "audio/webm" });
        if (blob.size > 1000) void sendToTizaIa({ audio: blob });
        else { setVoiceState("idle"); setVoiceError("La grabación quedó vacía. Inténtalo de nuevo."); }
      };
      recorderRef.current = recorder;
      setVoiceSeconds(0);
      setVoiceState("recording");
      setVoiceHint("Grabando… cuenta cómo estuvo la clase: qué hizo la docente, qué estrategias usó y qué destacarías.");
      recorder.start();
    } catch {
      setVoiceError("No se pudo acceder al micrófono. Revisa los permisos del navegador.");
    }
  };

  const stopRecording = () => {
    if (recorderRef.current?.state === "recording") recorderRef.current.stop();
    setVoiceHint("");
  };

  // Cuando el relato ya está escrito a mano, la IA lo ordena y completa la pauta.
  const improveWrittenNotes = () => {
    const written = [data.generalEvidence, data.improvements].map((item) => item.trim()).filter(Boolean).join("\n\n");
    if (!written) {
      setVoiceError("Escribe primero el relato en “Evidencia general” o graba un audio.");
      return;
    }
    void sendToTizaIa({ text: written });
  };

  const fieldLabel = "text-[11px] font-bold uppercase tracking-wide text-slate-500";
  const inputStyle = "mt-1 w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm outline-none transition focus:border-blue-500 focus:ring-4 focus:ring-blue-50";

  const totalIndicators = data.cultureItems.length + data.strengthItems.length + 3;
  const answeredIndicators = [...data.cultureItems, ...data.strengthItems, data.comprehensionUsed, data.thinkingUsed, data.climateUsed]
    .filter((value) => value === "si" || value === "no").length;
  const progressPct = Math.round((answeredIndicators / totalIndicators) * 100);

  // Portal a <body>: los contenedores animados de la app crean stacking contexts
  // que dejaban el modal atrapado bajo la barra superior.
  return createPortal(
    <div className="fixed inset-0 z-[200] flex items-end justify-center bg-slate-900/50 backdrop-blur-[2px] sm:items-center sm:p-6" onClick={saveAndClose}>
      <div className="flex h-[100dvh] w-full max-w-3xl flex-col bg-white shadow-2xl sm:h-auto sm:max-h-[90vh] sm:rounded-2xl" onClick={(event) => event.stopPropagation()}>
        <header className="flex items-start justify-between gap-3 border-b border-slate-100 bg-gradient-to-r from-blue-50 to-white px-4 pb-3 pt-[max(0.75rem,env(safe-area-inset-top))] sm:rounded-t-2xl sm:px-5 sm:py-4">
          <div className="min-w-0">
            <p className="text-xs font-bold uppercase tracking-wider text-blue-700">Pauta de acompañamiento de clase</p>
            <h2 className="mt-0.5 truncate text-base font-semibold text-slate-950 sm:text-lg">Feedback · {record.course || "Sin curso"}</h2>
            <p className="mt-0.5 truncate text-xs text-slate-500">{record.date || "Sin fecha"} · {record.topic || "Sin tema definido"}{(record.axis || record.characterStrength) ? ` · ${record.axis || record.characterStrength}` : ""}</p>
            <p className="mt-1 text-[11px] font-semibold text-blue-700">El correo se prepara con diseño editorial y se envía desde tu Gmail institucional.</p>
          </div>
          <button onClick={saveAndClose} className="rounded-lg border border-slate-200 bg-white p-2 text-slate-500 hover:bg-slate-50" title="Guardar y cerrar">
            <X className="h-4 w-4" />
          </button>
        </header>

        <div className="shrink-0 border-b border-slate-100 bg-white px-4 py-2 sm:px-5">
          <div className="flex items-center gap-3">
            <div className="h-1.5 flex-1 overflow-hidden rounded-full bg-slate-100">
              <div className={`h-full rounded-full transition-all duration-500 ${progressPct === 100 ? "bg-emerald-500" : "bg-blue-600"}`} style={{ width: `${progressPct}%` }} />
            </div>
            <span className={`shrink-0 text-[11px] font-black tabular-nums ${progressPct === 100 ? "text-emerald-600" : "text-slate-500"}`}>
              {answeredIndicators}/{totalIndicators}
            </span>
          </div>
        </div>

        <div className="min-h-0 flex-1 space-y-4 overflow-y-auto bg-slate-50/60 px-3 py-3 sm:space-y-5 sm:px-5 sm:py-4">
          <section className="overflow-hidden rounded-2xl bg-gradient-to-br from-indigo-600 to-violet-700 p-4 shadow-md shadow-indigo-900/15 sm:p-5">
            <div className="flex items-start gap-3">
              <span className="grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-white/15 text-white"><Sparkles className="h-4.5 w-4.5" /></span>
              <div className="min-w-0 flex-1">
                <p className="text-[9px] font-black uppercase tracking-[0.16em] text-indigo-200">Relato hablado</p>
                <h3 className="text-sm font-bold text-white">Cuéntale a Tiza-IA cómo estuvo la clase</h3>
                <p className="mt-1 text-[11px] leading-4 text-indigo-100">
                  Graba tu relato y la pauta se completa sola: marca los indicadores respaldados, reconoce las estrategias del cuadernillo Focus y redacta la evidencia. Nunca reemplaza lo que ya marcaste.
                </p>
              </div>
            </div>
            <div className="mt-3 flex flex-wrap items-center gap-2">
              {voiceState === "recording" ? (
                <button
                  type="button"
                  onClick={stopRecording}
                  className="inline-flex min-h-10 items-center gap-2 rounded-xl bg-white px-4 py-2 text-xs font-black text-rose-700 shadow-sm transition hover:bg-rose-50"
                >
                  <span className="h-2.5 w-2.5 animate-pulse rounded-sm bg-rose-600" />
                  Detener y analizar · {String(Math.floor(voiceSeconds / 60)).padStart(2, "0")}:{String(voiceSeconds % 60).padStart(2, "0")}
                </button>
              ) : (
                <button
                  type="button"
                  disabled={voiceState === "processing"}
                  onClick={startRecording}
                  className="inline-flex min-h-10 items-center gap-2 rounded-xl bg-white px-4 py-2 text-xs font-black text-indigo-700 shadow-sm transition hover:bg-indigo-50 disabled:opacity-60"
                >
                  {voiceState === "processing" ? <Loader2 className="h-4 w-4 animate-spin" /> : <Mic className="h-4 w-4" />}
                  {voiceState === "processing" ? "Analizando…" : "Grabar relato"}
                </button>
              )}
              <button
                type="button"
                disabled={voiceState !== "idle"}
                onClick={improveWrittenNotes}
                title="Usa lo que ya escribiste abajo para completar la pauta y mejorar la redacción"
                className="inline-flex min-h-10 items-center gap-2 rounded-xl bg-white/10 px-3.5 py-2 text-xs font-bold text-white ring-1 ring-white/25 transition hover:bg-white/20 disabled:opacity-50"
              >
                <Wand2 className="h-4 w-4" /> Mejorar lo escrito
              </button>
            </div>
            {voiceHint ? <p className="mt-2.5 rounded-lg bg-white/10 px-3 py-2 text-[11px] font-semibold leading-4 text-white">{voiceHint}</p> : null}
            {voiceError ? <p className="mt-2.5 rounded-lg bg-rose-950/40 px-3 py-2 text-[11px] font-semibold leading-4 text-rose-100 ring-1 ring-rose-300/30">{voiceError}</p> : null}
          </section>

          <section className="grid grid-cols-2 gap-4 rounded-2xl bg-white p-4 shadow-sm ring-1 ring-slate-100 sm:p-5 lg:grid-cols-3">
            <label className="col-span-2 block rounded-xl border border-slate-200 bg-white p-3 shadow-sm lg:col-span-3 sm:p-4">
              <span className={fieldLabel}>Nombre docente</span>
              <select
                value={testTeacherActive ? FEEDBACK_TEST_TEACHER.email : data.teacherEmail}
                onChange={(event) => {
                  const selected = FEEDBACK_TEACHER_OPTIONS.find((teacher) => teacher.email === event.target.value);
                  if (!selected) return;
                  if (selected.isTest) {
                    setTestTeacherActive(true);
                  } else {
                    setTestTeacherActive(false);
                    update({ teacher: selected.name, teacherEmail: selected.email });
                  }
                }}
                className={inputStyle}
              >
                {!data.teacherEmail ? <option value="">Selecciona un docente</option> : null}
                {FEEDBACK_TEACHER_OPTIONS.map((teacher) => (
                  <option key={teacher.email} value={teacher.email}>
                    {teacher.isTest ? "★ PRUEBA · " : ""}{teacher.name} · {teacher.email}{teacher.headship ? ` · ${teacher.headship}` : ""}
                  </option>
                ))}
              </select>
              <span className={`mt-2 block break-words px-0.5 text-[10px] font-semibold ${testTeacherActive ? "text-violet-700" : "text-slate-500"}`}>
                {testTeacherActive ? "Modo de prueba temporal · " : "Destinatario · "}{teacherEmail || "Sin correo seleccionado"}
              </span>
            </label>
            <label className="block">
              <span className={fieldLabel}>Asignatura</span>
              <input value={data.subject} onChange={(event) => update({ subject: event.target.value })} className={inputStyle} />
            </label>
            <label className="block">
              <span className={fieldLabel}>N° de acompañamiento</span>
              <input
                value={data.observationNumber}
                readOnly
                aria-readonly="true"
                className={`${inputStyle} cursor-default bg-slate-100 font-bold text-slate-700`}
              />
              <span className="mt-1.5 block text-[10px] font-semibold leading-4 text-slate-500">
                Calculado automáticamente según el orden de las clases realizadas del curso.
              </span>
            </label>
            <label className="block">
              <span className={fieldLabel}>Hora de inicio</span>
              <input type="time" value={data.startTime} onChange={(event) => update({ startTime: event.target.value })} className={inputStyle} />
            </label>
            <label className="block">
              <span className={fieldLabel}>Hora de término</span>
              <input type="time" value={data.endTime} onChange={(event) => update({ endTime: event.target.value })} className={inputStyle} />
            </label>
            <label className="col-span-2 block sm:col-span-1">
              <span className={fieldLabel}>Observador/a</span>
              <input value={data.observer} onChange={(event) => update({ observer: event.target.value })} className={inputStyle} />
            </label>
          </section>

          <FeedbackSectionCard number="01" eyebrow="Cultura institucional" title="Intervención formativa" accent="teal">
            <div className="divide-y divide-slate-100">
              {FEEDBACK_SECTION_CULTURE.map((item, index) => (
                <div key={item} className="flex flex-col items-start justify-between gap-2 py-3 first:pt-0 last:pb-0 sm:flex-row sm:items-center sm:gap-3">
                  <p className="text-[13px] leading-5 text-slate-700 sm:text-sm">{item}</p>
                  <FeedbackYesNo value={data.cultureItems[index]} onChange={(value) => updateItem("cultureItems", index, value)} />
                </div>
              ))}
            </div>
          </FeedbackSectionCard>

          <FeedbackSectionCard number="02" eyebrow="Formación del carácter" title="Fortalezas puestas en práctica" accent="violet">
            <div className="divide-y divide-slate-100">
              {FEEDBACK_SECTION_STRENGTHS.map((item, index) => (
                <div key={item} className="flex flex-col items-start justify-between gap-2 py-3 first:pt-0 last:pb-0 sm:flex-row sm:items-center sm:gap-3">
                  <p className="text-[13px] leading-5 text-slate-700 sm:text-sm">{item}</p>
                  <FeedbackYesNo value={data.strengthItems[index]} onChange={(value) => updateItem("strengthItems", index, value)} />
                </div>
              ))}
            </div>
          </FeedbackSectionCard>

          <FeedbackSectionCard number="03" eyebrow="Didáctica y ambiente" title="Estrategias pedagógicas observadas" accent="amber">
            <div className="space-y-3">
            <div className="rounded-xl border border-slate-200 p-3">
              <div className="flex flex-col items-start justify-between gap-2 sm:flex-row sm:items-center sm:gap-3">
                <p className="text-sm font-semibold text-slate-800">a. ¿Se observa uso de habilidad de comprensión?</p>
                <FeedbackYesNo value={data.comprehensionUsed} onChange={(value) => update({ comprehensionUsed: value })} />
              </div>
              {data.comprehensionUsed === "si" ? (
                <div className="mt-2 flex flex-wrap gap-2">
                  {FEEDBACK_COMPREHENSION_STRATEGIES.map((strategy) => {
                    const active = data.comprehensionStrategies.includes(strategy);
                    return (
                      <button
                        key={strategy}
                        type="button"
                        onClick={() => update({
                          comprehensionStrategies: active
                            ? data.comprehensionStrategies.filter((item) => item !== strategy)
                            : [...data.comprehensionStrategies, strategy],
                        })}
                        className={`rounded-lg px-3 py-1.5 text-xs font-bold ring-1 transition ${active ? "bg-blue-100 text-blue-700 ring-blue-300" : "bg-white text-slate-500 ring-slate-200 hover:bg-slate-50"}`}
                      >
                        {strategy}
                      </button>
                    );
                  })}
                </div>
              ) : null}
              <label className="mt-2 block">
                <span className={fieldLabel}>Evidencia</span>
                <textarea value={data.comprehensionEvidence} onChange={(event) => update({ comprehensionEvidence: event.target.value })} rows={2} className={`${inputStyle} resize-y`} />
              </label>
            </div>
            <div className="rounded-xl border border-slate-200 p-3">
              <div className="flex flex-col items-start justify-between gap-2 sm:flex-row sm:items-center sm:gap-3">
                <p className="text-sm font-semibold text-slate-800">b. ¿Utiliza estrategia de pensamiento?</p>
                <FeedbackYesNo value={data.thinkingUsed} onChange={(value) => update({ thinkingUsed: value })} />
              </div>
              <StrategyMultiSelect
                catalog={THINKING_STRATEGIES}
                selected={data.thinkingStrategies}
                onChange={(thinkingStrategies) => update({ thinkingStrategies })}
                accent="violet"
                emptyLabel="Sin estrategias de pensamiento seleccionadas."
              />
              <label className="mt-2 block">
                <span className={fieldLabel}>Detalle o estrategia fuera del cuadernillo</span>
                <textarea value={data.thinkingDetail} onChange={(event) => update({ thinkingDetail: event.target.value })} rows={2} className={`${inputStyle} resize-y`} />
              </label>
            </div>
            <div className="rounded-xl border border-slate-200 p-3">
              <div className="flex flex-col items-start justify-between gap-2 sm:flex-row sm:items-center sm:gap-3">
                <p className="text-sm font-semibold text-slate-800">c. ¿Utiliza estrategia de clima de aula?</p>
                <FeedbackYesNo value={data.climateUsed} onChange={(value) => update({ climateUsed: value })} />
              </div>
              <StrategyMultiSelect
                catalog={CLIMATE_STRATEGIES}
                selected={data.climateStrategies}
                onChange={(climateStrategies) => update({ climateStrategies })}
                accent="rose"
                emptyLabel="Sin estrategias de clima seleccionadas."
              />
              <label className="mt-2 block">
                <span className={fieldLabel}>Detalle o estrategia fuera del cuadernillo</span>
                <textarea value={data.climateDetail} onChange={(event) => update({ climateDetail: event.target.value })} rows={2} className={`${inputStyle} resize-y`} />
              </label>
            </div>
            </div>
          </FeedbackSectionCard>

          <FeedbackSectionCard number="04" eyebrow="Lo observado" title="Evidencia y observaciones generales" accent="slate">
            <textarea value={data.generalEvidence} onChange={(event) => update({ generalEvidence: event.target.value })} rows={4} placeholder="Registro de lo observado durante la clase." className={`${inputStyle} mt-0 resize-y`} />
          </FeedbackSectionCard>

          <FeedbackSectionCard number="05" eyebrow="Cierre" title="Elementos destacados y sugerencias" accent="slate">
            <textarea value={data.improvements} onChange={(event) => update({ improvements: event.target.value })} rows={4} placeholder="Lo que se destaca de la clase y las sugerencias concretas para la docente." className={`${inputStyle} mt-0 resize-y`} />
          </FeedbackSectionCard>
        </div>

        {previewHtml ? (
          <div className="shrink-0 border-t border-slate-200 bg-white">
            <div className="flex items-center justify-between gap-2 px-4 py-2">
              <p className="text-[11px] font-bold uppercase tracking-wide text-slate-500">Vista previa · mantén presionado, selecciona todo y copia</p>
              <button onClick={() => setPreviewHtml("")} className="rounded-lg border border-slate-200 bg-white px-2 py-1 text-[11px] font-bold text-slate-600 hover:bg-slate-50">Cerrar</button>
            </div>
            <div className="max-h-64 overflow-auto border-t border-slate-100 px-3 py-3" dangerouslySetInnerHTML={{ __html: previewHtml }} />
          </div>
        ) : null}
        {emailHint ? (
          <div className={`shrink-0 border-t px-4 py-2.5 text-xs font-semibold ${emailState === "error" ? "border-rose-100 bg-rose-50 text-rose-700" : "border-blue-100 bg-blue-50 text-blue-800"}`}>
            {emailHint}
          </div>
        ) : null}
        <footer className="grid shrink-0 grid-cols-2 gap-2 border-t border-slate-100 bg-slate-50 px-3 py-3 pb-[max(0.75rem,env(safe-area-inset-bottom))] sm:flex sm:flex-wrap sm:items-center sm:justify-between sm:rounded-b-2xl sm:px-5">
          <div className="contents sm:flex sm:gap-2">
            <button onClick={copySummary} className="inline-flex min-h-10 items-center justify-center gap-2 rounded-xl border border-slate-200 bg-white px-3 py-2 text-xs font-bold text-slate-700 hover:bg-slate-50">
              <Copy className="h-4 w-4" /> {copied ? "¡Copiado!" : "Copiar texto"}
            </button>
            <button
              onClick={() => setPreviewHtml(previewHtml ? "" : classFeedbackEmailHtml(record, emailFeedbackData))}
              title="Muestra el correo tal como se verá, para copiarlo a mano si el celular no conserva el formato"
              className="inline-flex min-h-10 items-center justify-center gap-2 rounded-xl border border-slate-200 bg-white px-3 py-2 text-xs font-bold text-slate-700 hover:bg-slate-50"
            >
              <FileText className="h-4 w-4" /> {previewHtml ? "Ocultar diseño" : "Ver diseño"}
            </button>
            <button
              onClick={printFeedbackPdf}
              title="Genera el PDF con el diseño intacto para adjuntarlo al correo (recomendado en celular)"
              className="inline-flex min-h-10 items-center justify-center gap-2 rounded-xl border border-emerald-200 bg-emerald-50 px-3 py-2 text-xs font-bold text-emerald-700 hover:bg-emerald-100"
            >
              <Printer className="h-4 w-4" /> PDF
            </button>
          </div>
          <div className="contents sm:flex sm:gap-2">
            {record.classFeedback ? (
              <button onClick={deleteFeedback} className="inline-flex min-h-10 items-center justify-center gap-2 rounded-xl border border-rose-200 bg-white px-3 py-2 text-xs font-bold text-rose-700 hover:bg-rose-50 sm:px-4">
                <Trash2 className="h-4 w-4" /> Eliminar feedback
              </button>
            ) : null}
            <button onClick={saveAndClose} className="min-h-10 rounded-xl border border-slate-200 bg-white px-3 py-2 text-xs font-bold text-slate-600 hover:bg-slate-50 sm:px-4">
              Guardar y cerrar
            </button>
            <button onClick={saveFeedback} className="inline-flex min-h-10 items-center justify-center gap-2 rounded-xl border border-violet-200 bg-violet-50 px-3 py-2 text-xs font-bold text-violet-700 hover:bg-violet-100 sm:px-4">
              <Save className="h-4 w-4" /> Guardar borrador
            </button>
            <button onClick={openFeedbackInGmail} title={teacherEmail ? `Copiar el diseño y preparar correo para ${teacherEmail}` : "No se encontró el correo de la profesora jefe"} className="col-span-2 inline-flex min-h-11 items-center justify-center gap-2 rounded-xl bg-gradient-to-r from-blue-700 to-indigo-700 px-5 py-2.5 text-xs font-bold text-white shadow-md shadow-blue-900/15 transition hover:from-blue-800 hover:to-indigo-800 sm:text-sm">
              <Mail className="h-4 w-4" /> Copiar diseño y abrir Gmail
            </button>
          </div>
        </footer>
      </div>
    </div>,
    document.body,
  );
}

// Historial de feedbacks de clase: listado consultable y reporte generado por Tiza-IA.
function FeedbackHistoryModal({
  records,
  ownerName,
  accessToken,
  onClose,
  onOpenFeedback,
  onDeleteFeedback,
}: {
  records: DataRecord[];
  ownerName: string;
  accessToken: string;
  onClose: () => void;
  onOpenFeedback: (recordId: string) => void;
  onDeleteFeedback: (recordId: string) => void;
}) {
  const [search, setSearch] = useState("");
  const [report, setReport] = useState("");
  const [reportLoading, setReportLoading] = useState(false);
  const [reportError, setReportError] = useState("");
  const [copied, setCopied] = useState(false);

  const withFeedback = records
    .filter((record) => record.classFeedback)
    .sort((a, b) => (b.date || "").localeCompare(a.date || ""));

  const filtered = withFeedback.filter((record) => {
    if (!search.trim()) return true;
    const data = parseClassFeedback(record.classFeedback);
    return normalize(`${record.course} ${record.date} ${record.topic} ${data.teacher} ${data.improvements} ${data.generalEvidence}`).includes(normalize(search));
  });

  const generateReport = async () => {
    setReportLoading(true);
    setReportError("");
    setReport("");
    try {
      const summaries = withFeedback
        .map((record) => classFeedbackSummaryText(record, parseClassFeedback(record.classFeedback)))
        .join("\n\n----------------------------------------\n\n");
      const message = [
        `Eres asistente del orientador ${ownerName} del Colegio San Lucas. A continuación tienes TODOS los feedbacks de acompañamiento de clase registrados durante el año (pauta institucional con indicadores Sí/No y observaciones).`,
        "Genera un REPORTE HISTÓRICO PROFESIONAL de estos acompañamientos, en español, con esta estructura:",
        "1. Resumen general (total de observaciones, período cubierto, cursos y docentes acompañados).",
        "2. Fortalezas observadas con mayor frecuencia (indicadores marcados Sí de forma consistente).",
        "3. Oportunidades de mejora recurrentes (indicadores marcados No y patrones en las sugerencias).",
        "4. Análisis por curso/docente cuando haya más de una observación.",
        "5. Recomendaciones concretas para el próximo período.",
        "Usa un tono profesional y constructivo, apto para compartir con el equipo directivo. No inventes datos que no estén en los feedbacks.",
        "",
        "FEEDBACKS REGISTRADOS:",
        summaries,
      ].join("\n");
      const fd = new FormData();
      fd.append("message", message);
      fd.append("today", new Date().toISOString().slice(0, 10));
      fd.append("roster", "[]");
      fd.append("courses", "[]");
      fd.append("dataContext", "");
      const res = await fetch("/api/ai/chat", {
        method: "POST",
        headers: { authorization: `Bearer ${accessToken}` },
        body: fd,
      });
      const payload = await res.json().catch(() => null) as { ok?: boolean; error?: unknown; result?: { answer?: string; summary?: string } } | null;
      if (!res.ok || !payload?.ok) {
        const errField = payload?.error;
        throw new Error(typeof errField === "string" ? errField : `Tiza-IA no pudo generar el reporte (${res.status}).`);
      }
      const text = payload.result?.answer || payload.result?.summary || "";
      if (!text.trim()) throw new Error("Tiza-IA devolvió una respuesta vacía. Intenta de nuevo.");
      setReport(text);
    } catch (error) {
      setReportError(error instanceof Error ? error.message : "No se pudo generar el reporte.");
    } finally {
      setReportLoading(false);
    }
  };

  const copyReport = async () => {
    try {
      await navigator.clipboard.writeText(report);
      setCopied(true);
      window.setTimeout(() => setCopied(false), 2500);
    } catch {
      window.prompt("Copia el reporte manualmente:", report);
    }
  };

  return createPortal(
    <div className="fixed inset-0 z-[200] flex items-end justify-center bg-slate-900/50 backdrop-blur-[2px] sm:items-center sm:p-6" onClick={onClose}>
      <div className="flex h-[94dvh] w-full max-w-3xl flex-col rounded-t-2xl bg-white shadow-2xl sm:h-auto sm:max-h-[90vh] sm:rounded-2xl" onClick={(event) => event.stopPropagation()}>
        <header className="flex items-start justify-between gap-3 rounded-t-2xl border-b border-slate-100 bg-gradient-to-r from-violet-50 to-white px-5 py-4">
          <div>
            <p className="text-xs font-bold uppercase tracking-wider text-violet-700">Acompañamiento de clases</p>
            <h2 className="text-lg font-semibold text-slate-950">Historial de feedbacks</h2>
            <p className="mt-0.5 text-xs text-slate-500">{withFeedback.length} feedback{withFeedback.length === 1 ? "" : "s"} registrado{withFeedback.length === 1 ? "" : "s"} · {ownerName}</p>
          </div>
          <button onClick={onClose} className="rounded-lg border border-slate-200 bg-white p-2 text-slate-500 hover:bg-slate-50" title="Cerrar">
            <X className="h-4 w-4" />
          </button>
        </header>

        <div className="min-h-0 flex-1 space-y-4 overflow-y-auto px-4 py-4 sm:px-5">
          <div className="flex flex-wrap items-center gap-2">
            <label className="relative min-w-48 flex-1">
              <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
              <input
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                placeholder="Buscar por curso, docente o contenido…"
                className="w-full rounded-lg border border-slate-200 bg-white py-2 pl-9 pr-3 text-sm outline-none focus:border-violet-400"
              />
            </label>
            <button
              onClick={generateReport}
              disabled={reportLoading || withFeedback.length === 0}
              className="inline-flex items-center gap-2 rounded-lg bg-violet-600 px-3 py-2 text-xs font-bold text-white shadow hover:bg-violet-700 disabled:bg-slate-300"
            >
              <TizaIaIcon className="h-4 w-4" /> {reportLoading ? "Generando reporte…" : "Reporte histórico con IA"}
            </button>
          </div>

          {reportError ? (
            <p className="rounded-lg border border-rose-200 bg-rose-50 px-3 py-2 text-xs font-semibold text-rose-700">{reportError}</p>
          ) : null}

          {report ? (
            <section className="rounded-xl border border-violet-200 bg-violet-50/40">
              <div className="flex items-center justify-between gap-2 border-b border-violet-100 px-3 py-2">
                <p className="text-xs font-bold uppercase tracking-wider text-violet-700">Reporte histórico generado por Tiza-IA</p>
                <button onClick={copyReport} className="inline-flex items-center gap-1.5 rounded-md border border-violet-200 bg-white px-2.5 py-1.5 text-[11px] font-bold text-violet-700 hover:bg-violet-100">
                  <Copy className="h-3.5 w-3.5" /> {copied ? "¡Copiado!" : "Copiar"}
                </button>
              </div>
              <div className="max-h-80 overflow-y-auto whitespace-pre-wrap px-4 py-3 text-sm leading-relaxed text-slate-800">{report}</div>
            </section>
          ) : null}

          {withFeedback.length === 0 ? (
            <p className="rounded-xl border border-dashed border-slate-300 bg-slate-50 p-6 text-center text-sm text-slate-500">
              Aún no hay feedbacks registrados. Marca una clase como realizada y usa el botón Feedback para crear el primero.
            </p>
          ) : filtered.length === 0 ? (
            <p className="rounded-xl border border-dashed border-slate-300 bg-slate-50 p-6 text-center text-sm text-slate-500">
              Ningún feedback coincide con la búsqueda.
            </p>
          ) : (
            <div className="divide-y divide-slate-100 overflow-hidden rounded-xl border border-slate-200">
              {filtered.map((record) => {
                const data = parseClassFeedback(record.classFeedback);
                const yesCount = [...data.cultureItems, ...data.strengthItems].filter((item) => item === "si").length;
                const totalMarked = [...data.cultureItems, ...data.strengthItems].filter(Boolean).length;
                return (
                  <div key={record.id} className="flex items-stretch bg-white transition hover:bg-violet-50/50">
                    <button
                      type="button"
                      onClick={() => onOpenFeedback(record.id)}
                      className="flex min-w-0 flex-1 items-center justify-between gap-3 px-3 py-2.5 text-left"
                    >
                      <div className="min-w-0">
                        <p className="text-sm font-bold text-slate-950">
                          {record.course || "Sin curso"} · {record.date || "Sin fecha"}
                          {data.observationNumber ? <span className="ml-1.5 rounded-full bg-violet-100 px-1.5 py-0.5 text-[10px] font-bold text-violet-700">Acomp. N° {data.observationNumber}</span> : null}
                        </p>
                        <p className="mt-0.5 line-clamp-1 text-xs text-slate-500">
                          {data.teacher ? `${data.teacher} · ` : ""}{record.topic || "Sin tema"}
                        </p>
                        {data.improvements.trim() ? <p className="mt-0.5 line-clamp-1 text-xs text-amber-800">{data.improvements.trim()}</p> : null}
                      </div>
                      <div className="shrink-0 text-right">
                        {totalMarked ? <p className="text-xs font-bold text-emerald-700">{yesCount}/{totalMarked} logrados</p> : null}
                        <p className="text-[10px] font-semibold uppercase tracking-wide text-slate-400">Abrir</p>
                      </div>
                    </button>
                    <button
                      type="button"
                      onClick={() => {
                        if (!window.confirm(`¿Eliminar definitivamente el feedback de ${record.course || "esta clase"}${record.date ? ` del ${record.date}` : ""}? La clase se conservará.`)) return;
                        onDeleteFeedback(record.id);
                      }}
                      title="Eliminar este feedback"
                      aria-label={`Eliminar feedback de ${record.course || "la clase"}`}
                      className="grid w-12 shrink-0 place-items-center border-l border-slate-100 text-slate-400 transition hover:bg-rose-50 hover:text-rose-700"
                    >
                      <Trash2 className="h-4 w-4" />
                    </button>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>
    </div>,
    document.body,
  );
}

const hasOrientationRecordContent = (record: DataRecord | Record<string, string>) => Boolean(
  (record.canvaLink || record.evidence || record.planificacion || record.folderLink || record.teacherLink || meaningfulOrientationNotes(record as DataRecord) || "").trim(),
);

// El título de la clase es siempre el campo "Tema / comentario". Solo cuando el
// tema falta o es genérico ("Sesión 1") se recurre a las observaciones o al
// nombre de la planificación; nunca a un link, que antes se colaba como título.
const getOrientationDisplayTitle = (record: DataRecord | Record<string, string>) => {
  const topic = String(record.topic || "").trim();
  const usableTopic = topic && !isPlaceholderOrientationText(topic) ? topic : "";
  if (usableTopic && !isGenericOrientationTopic(usableTopic)) return usableTopic;

  const descriptive = [meaningfulOrientationNotes(record as DataRecord), record.planificacion]
    .map((value) => String(value || "").trim())
    .find((value) => value && !isPlaceholderOrientationText(value) && !isLinkLikeText(value));
  if (descriptive) return descriptive;
  if (usableTopic) return usableTopic;

  const action = String(record.axis || record.characterStrength || record.classType || "").trim();
  return action && !isPlaceholderOrientationText(action) ? action : "Sin tema definido";
};

const isGeneratedOrientationPlaceholder = (record: DataRecord) => {
  const generatedPlan = normalize(record.source || "").includes("plan anual orientacion 2026");
  if (!generatedPlan) return false;
  return !hasOrientationRecordContent(record);
};

const orientationSeedIdentity = (record: DataRecord | Record<string, string>) => normalize([
  record.date,
  record.week,
  record.course,
  record.axis || record.characterStrength,
  record.topic || meaningfulOrientationNotes(record as DataRecord) || record.notes || record.planificacion,
].filter(Boolean).join("|"));

const parseInterventions = (value: string | undefined): CaseIntervention[] => {
  if (!value) return [];
  try {
    const parsed = JSON.parse(value);
    if (!Array.isArray(parsed)) return [];
    return parsed
      .filter((i) => i && typeof i.action === "string")
      .map((i) => ({
        id: i.id || uid(),
        date: i.date || "",
        action: i.action || "",
        by: i.by || "",
        outcome: i.outcome || "",
      }));
  } catch {
    return [];
  }
};

const formatDateTime = (value: string | undefined) => {
  if (!value) return "";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return date.toLocaleString("es-CL", { dateStyle: "medium", timeStyle: "short" });
};

const parseGenogram = (value: string | undefined): GenogramMember[] => {
  if (!value) return [];
  try {
    const parsed = JSON.parse(value);
    if (!Array.isArray(parsed)) return [];
    return parsed
      .filter((member) => member && typeof member.name === "string" && typeof member.relation === "string")
      .map((member) => ({
        id: member.id || uid(),
        name: member.name || "",
        relation: member.relation || "Otro familiar",
        role: member.role || "Red significativa",
        age: member.age || "",
        phone: member.phone || "",
        email: member.email || "",
        address: member.address || "",
        notes: member.notes || "",
        x: typeof member.x === "number" ? member.x : undefined,
        y: typeof member.y === "number" ? member.y : undefined,
      }));
  } catch {
    return [];
  }
};

